export const INSP_I18N = {
pt: [ {day:"Hoje",title:"Comece com silêncio",body:"Antes das notificações, antes das notícias: trinta segundos com o Sinal da Cruz e um Pai-Nosso devagar. O dia pode esperar. O Céu está ansioso para encontrar você.",tag:"Manhã"}, {day:"Hoje",title:"Leve um nome com você",body:"Escreva hoje um nome na sua mão: alguém que precisa de oração. Cada vez que olhar, reze uma Ave-Maria. Ao anoitecer terá rezado um rosário sem perceber.",tag:"Prática"}, {day:"Arquivo",title:"O ministério do banco",body:"Sente-se perto dos recém-chegados. Aprenda um nome cada domingo. As paróquias não crescem primeiro com programas, mas com nomes lembrados.",tag:"Comunidade"}, {day:"Arquivo",title:"A confissão é um recomeço, não um relatório",body:"Você não vai enumerar fracassos; vai ser encontrado. Sábado 4 PM. Dez minutos. Sairá mais leve do que entrou.",tag:"Misericórdia"}, {day:"Arquivo",title:"Adoração ao meio-dia",body:"Doze minutos numa capela silenciosa valem mais que uma hora de tela. Não leve nada além do seu cansaço. Ele pediu sua companhia, não seu desempenho.",tag:"Oração"} ],
it: [ {day:"Oggi",title:"Comincia con il silenzio",body:"Prima delle notifiche, prima delle notizie: trenta secondi con il Segno della Croce e un Padre nostro lento. Il giorno può aspettare. Il Cielo desidera incontrarti.",tag:"Mattina"}, {day:"Oggi",title:"Porta con te un nome",body:"Scrivi oggi un nome sulla tua mano: qualcuno che ha bisogno di preghiera. Ogni volta che lo vedi, recita un’Ave Maria. A sera avrai recitato un rosario senza accorgertene.",tag:"Pratica"}, {day:"Archivio",title:"Il ministero del banco",body:"Siediti vicino ai nuovi arrivati. Impara un nome ogni domenica. Le parrocchie non crescono prima con i programmi, ma con i nomi ricordati.",tag:"Comunità"}, {day:"Archivio",title:"La confessione è un nuovo inizio, non un resoconto",body:"Non vai a elencare fallimenti; vai a essere ritrovato. Sabato ore 16. Dieci minuti. Uscirai più leggero di come sei entrato.",tag:"Misericordia"}, {day:"Archivio",title:"Adorazione a mezzogiorno",body:"Dodici minuti in una cappella silenziosa valgono più di un’ora di schermo. Non portare altro che la tua stanchezza. Lui ha chiesto la tua compagnia, non la tua prestazione.",tag:"Preghiera"} ],
la: [ {day:"Hodie",title:"Incipe cum silentio",body:"Ante nuntios, ante nova: triginta secunda cum Signo Crucis et uno Pater noster lento. Dies exspectare potest. Caelum te convenire cupit.",tag:"Mane"}, {day:"Hodie",title:"Fer tecum nomen",body:"Scribe hodie nomen in manu tua: aliquem qui oratione indiget. Quoties videris, ora Ave Maria. Sub vesperum rosarium nesciens oraveris.",tag:"Praxis"}, {day:"Archivum",title:"Ministerium subsellii",body:"Sede prope novos venientes. Disce unum nomen omni dominica. Paroeciae non primum programmatibus crescunt, sed nominibus recordatis.",tag:"Communitas"}, {day:"Archivum",title:"Confessio est initium, non relatio",body:"Non vadis ut defectus enumeres; vadis ut inveniaris. Sabbato hora 16. Decem minuta. Levior exibis quam intrasti.",tag:"Misericordia"}, {day:"Archivum",title:"Adoratio meridie",body:"Duodecim minuta in sacello silenti plus valent quam hora scrinii. Nihil fer praeter lassitudinem tuam. Societatem tuam petivit, non praestationem.",tag:"Oratio"} ],
fr: [ {day:"Aujourd’hui",title:"Commence par le silence",body:"Avant les notifications, avant les nouvelles : trente secondes avec le Signe de la Croix et un Notre Père lent. Le jour peut attendre. Le Ciel désire te rencontrer.",tag:"Matin"}, {day:"Aujourd’hui",title:"Porte un nom avec toi",body:"Écris aujourd’hui un nom sur ta main : quelqu’un qui a besoin de prière. Chaque fois que tu le vois, dis un Je vous salue Marie. Au soir tu auras dit un chapelet sans t’en rendre compte.",tag:"Pratique"}, {day:"Archives",title:"Le ministère du banc",body:"Assieds-toi près des nouveaux venus. Apprends un nom chaque dimanche. Les paroisses ne grandissent pas d’abord par des programmes, mais par des noms retenus.",tag:"Communauté"}, {day:"Archives",title:"La confession est un nouveau départ, pas un rapport",body:"Tu ne vas pas énumérer des échecs ; tu vas être retrouvé. Samedi 16h. Dix minutes. Tu ressortiras plus léger que tu n’es entré.",tag:"Miséricorde"}, {day:"Archives",title:"Adoration à midi",body:"Douze minutes dans une chapelle silencieuse valent mieux qu’une heure d’écran. N’apporte rien que ta fatigue. Il a demandé ta compagnie, pas ta performance.",tag:"Prière"} ],
};
INSP_I18N.zh = [ {day:"今天",title:"从静默开始",body:"在通知之前，在新闻之前：用十字圣号和一遍缓慢的天主经开始三十秒。白天可以等，天堂渴望与你相遇。",tag:"早晨"}, {day:"今天",title:"带上一个名字",body:"今天在手上写一个名字：一位需要祈祷的人。每次看到，就念一遍圣母经。到黄昏时你已不知不觉念完了一串玫瑰经。",tag:"实践"}, {day:"存档",title:"长椅的职务",body:"坐在新来者附近，每个主日记住一个名字。堂区首先不是靠计划增长，而是靠被记住的名字。",tag:"团体"}, {day:"存档",title:"告解是重新开始，不是汇报",body:"你不是去列举失败，而是去被寻回。周六下午4点，十分钟，你会比进去时更轻松地出来。",tag:"慈悲"}, {day:"存档",title:"正午的朝拜",body:"在安静小堂里的十二分钟胜过一小时的屏幕。只带上你的疲惫，祂要的是你的陪伴，不是你的表现。",tag:"祈祷"} ];
INSP_I18N.tl = [ {day:"Ngayon",title:"Magsimula sa katahimikan",body:"Bago ang notifications, bago ang balita: tatlumpung segundo ng Tanda ng Krus at isang mabagal na Ama Namin. Makapaghihintay ang araw. Nananabik ang Langit na makilala ka.",tag:"Umaga"}, {day:"Ngayon",title:"Magdala ng isang pangalan",body:"Magsulat ngayon ng isang pangalan sa iyong kamay: isang taong nangangailangan ng panalangin. Sa tuwing makikita mo ito, magdasal ng Aba Ginoong Maria. Pagsapit ng gabi nakapagrosaryo ka na nang hindi namamalayan.",tag:"Gawain"}, {day:"Baul",title:"Ang ministri ng upuan",body:"Umupo malapit sa mga bagong dating. Matuto ng isang pangalan tuwing Linggo. Ang mga parokya ay hindi unang lumalago sa programa, kundi sa mga naaalalang pangalan.",tag:"Pamayanan"}, {day:"Baul",title:"Ang kumpisal ay panibagong simula, hindi ulat",body:"Hindi ka pupunta para maglista ng kabiguan; pupunta ka para matagpuan. Sabado 4 PM. Sampung minuto. Lalabas kang mas magaan kaysa pagpasok mo.",tag:"Awa"}, {day:"Baul",title:"Adorasyon sa tanghali",body:"Labindalawang minuto sa tahimik na kapilya ay higit sa isang oras ng screen. Wala kang dadalhin kundi ang pagod mo. Ang hiniling Niya ay ang iyong piling, hindi ang iyong galing.",tag:"Panalangin"} ];
INSP_I18N.vi = [ {day:"Hôm nay",title:"Bắt đầu bằng thinh lặng",body:"Trước các thông báo, trước tin tức: ba mươi giây với Dấu Thánh Giá và một kinh Lạy Cha chậm rãi. Ngày mới có thể chờ. Thiên Đàng khao khát gặp bạn.",tag:"Buổi sáng"}, {day:"Hôm nay",title:"Mang theo một cái tên",body:"Hôm nay hãy viết một cái tên lên tay bạn: người đang cần cầu nguyện. Mỗi lần nhìn thấy, hãy đọc một kinh Kính Mừng. Đến tối bạn đã lần xong một chuỗi Mân Côi mà không hay.",tag:"Thực hành"}, {day:"Lưu trữ",title:"Tác vụ của hàng ghế",body:"Hãy ngồi gần những người mới đến. Mỗi Chúa nhật học một cái tên. Giáo xứ không lớn lên trước hết nhờ chương trình, mà nhờ những cái tên được nhớ đến.",tag:"Cộng đoàn"}, {day:"Lưu trữ",title:"Xưng tội là khởi đầu mới, không phải bản báo cáo",body:"Bạn không đến để liệt kê thất bại; bạn đến để được tìm thấy. Thứ bảy 4 giờ chiều. Mười phút. Bạn sẽ bước ra nhẹ nhõm hơn lúc bước vào.",tag:"Lòng thương xót"}, {day:"Lưu trữ",title:"Chầu Thánh Thể buổi trưa",body:"Mười hai phút trong nhà nguyện thinh lặng quý hơn một giờ dán mắt vào màn hình. Đừng mang gì ngoài sự mệt mỏi của bạn. Người xin bạn ở lại với Người, chứ không đòi thành tích.",tag:"Cầu nguyện"} ];
INSP_I18N.ar = [ {day:"اليوم",title:"ابدأ بالصمت",body:"قبل التنبيهات وقبل الأخبار: ثلاثون ثانية مع إشارة الصليب وأبانا الذي بتمهُّل. النهار يمكنه الانتظار. السماء تتوق للقائك.",tag:"الصباح"}, {day:"اليوم",title:"احمل اسمًا معك",body:"اكتب اليوم اسمًا على يدك: شخص يحتاج إلى الصلاة. كلما رأيته صلِّ السلام الملائكي. عند المساء تكون قد صليت مسبحة دون أن تشعر.",tag:"ممارسة"}, {day:"الأرشيف",title:"خدمة المقعد",body:"اجلس قرب الوافدين الجدد. تعلَّم اسمًا كل أحد. الرعايا لا تنمو أولًا بالبرامج بل بالأسماء المتذكَّرة.",tag:"الجماعة"}, {day:"الأرشيف",title:"الاعتراف بداية جديدة لا تقرير",body:"أنت لا تذهب لتعدّد الإخفاقات بل لتُوجَد. السبت 4 مساءً. عشر دقائق. ستخرج أخف مما دخلت.",tag:"الرحمة"}, {day:"الأرشيف",title:"سجود الظهيرة",body:"اثنتا عشرة دقيقة في كنيسة صامتة خير من ساعة أمام الشاشة. لا تحمل سوى تعبك. لقد طلب صحبتك لا أداءك.",tag:"الصلاة"} ];
INSP_I18N.ko = [ {day:"오늘",title:"침묵으로 시작하기",body:"알림보다 먼저, 소식보다 먼저: 십자 성호와 느린 주님의 기도로 30초. 하루는 기다릴 수 있습니다. 하늘이 당신 만나기를 간절히 바랍니다.",tag:"아침"}, {day:"오늘",title:"이름 하나 가지고 다니기",body:"오늘 손에 이름 하나를 적으세요. 기도가 필요한 사람입니다. 볼 때마다 성모송을 바치세요. 저녁이면 어느새 묵주기도를 마치게 됩니다.",tag:"실천"}, {day:"보관함",title:"의자의 직무",body:"새로 오신 분 가까이에 앉으세요. 매 주일 이름 하나를 외우세요. 본당은 프로그램으로 먼저 크는 것이 아니라 기억된 이름으로 큽니다.",tag:"공동체"}, {day:"보관함",title:"고해는 보고가 아니라 새 출발",body:"실패를 나열하러 가는 것이 아니라 발견되러 가는 것입니다. 토요일 오후 4시, 10분이면 들어갈 때보다 가볍게 나오게 됩니다.",tag:"자비"}, {day:"보관함",title:"정오의 성체조배",body:"고요한 경당에서의 12분이 화면 앞 1시간보다 낫습니다. 피로 외에는 아무것도 가져오지 마세요. 그분은 당신의 성과가 아니라 동행을 바라십니다.",tag:"기도"} ];
