SAINT1L.it["Joseph"] = "Custode di Gesù e Maria; uomo giusto, patrono dei padri e dei lavoratori.";
SAINT1L.it["Justin of Naplouse"] = "Filosofo convertito che difese la fede con gli scritti; martire a Roma.";
SAINT1L.it["Kateri Tekakwitha"] = "Giovane mohawk, il «Giglio dei Mohawk», fedele a Cristo tra i suoi.";
SAINT1L.it["Lawrence"] = "Diacono romano che distribuì i beni ai poveri prima del martirio.";
SAINT1L.it["Leo the Great"] = "Papa che definì la fede in Cristo e liberò Roma da Attila con la parola.";
SAINT1L.it["Lucy of Syracuse"] = "Giovane martire siracusana, simbolo di purezza e fortezza.";
SAINT1L.it["Luke"] = "Medico e compagno di Paolo; scrisse il terzo Vangelo e gli Atti.";
SAINT1L.it["Mark"] = "Segretario di Pietro a Roma; mise per iscritto la sua predicazione nel Vangelo.";
SAINT1L.it["Martha"] = "Sorella di Maria e Lazzaro, serva di Gesù e donna di grande fede.";
SAINT1L.it["Martin of Tours"] = "Soldato che divise il mantello con un povero; vescovo e apostolo della Gallia.";
SAINT1L.it["Mary Magdalen"] = "Testimone della croce e prima del Risorto; annunciatrice agli apostoli.";
SAINT1L.it["Matthew"] = "Pubblicano chiamato da Gesù; il suo Vangelo presenta il Cristo promesso.";
SAINT1L.it["Matthias"] = "Eletto dagli apostoli per occupare il posto di Giuda.";
SAINT1L.it["Maximilian Kolbe"] = "Francescano che diede la vita per un padre di famiglia ad Auschwitz.";
SAINT1L.it["Michael"] = "Arcangelo principe della milizia celeste; «chi come Dio?».";
SAINT1L.it["Monica"] = "Madre di Agostino; con lacrime e preghiera perseverante lo vide convertito.";
SAINT1L.it["Our Lady of Guadalupe"] = "La Morenita del Tepeyac (1531), madre e segno di unità dell’America.";
SAINT1L.it["Our Lady of the Rosary"] = "Invocazione mariana del Rosario, memoria della vittoria di Lepanto.";
SAINT1L.it["Peter"] = "Pescatore di Galilea, primo Papa; rinnegò, pianse e confermò i fratelli.";
SAINT1L.it["Peter Claver"] = "Gesuita che battezzò e servì centinaia di migliaia di schiavi a Cartagena.";
SAINT1L.it["Philip"] = "Apostolo che condusse Natanaele a Gesù e chiese di vedere il Padre.";
SAINT1L.it["Philip Neri"] = "Sacerdote romano allegro, amico dei giovani; fondò l’Oratorio.";
SAINT1L.it["Pius X"] = "Papa che avvicinò la comunione frequente ai fedeli e combatté il modernismo.";
SAINT1L.it["Scholastica"] = "Sorella di Benedetto e badessa; consacrò la vita alla preghiera.";
SAINT1L.it["Teresa of Avila"] = "Riformatrice del Carmelo e dottoressa; «solo Dio basta».";
SAINT1L.it["The Assumption of the Blessed Virgin Mary"] = "Maria, al termine della vita, fu assunta in cielo in corpo e anima.";
SAINT1L.it["The Baptism of Our Lord"] = "Gesù è battezzato da Giovanni: inizia la vita pubblica.";
SAINT1L.it["The Conversion of Saint Paul"] = "Saulo, persecutore, cadde a Damasco e si fece apostolo delle nazioni.";
SAINT1L.it["The Epiphany of Our Lord"] = "I Magi adorano il Bambino: Cristo si manifesta a tutte le nazioni.";
SAINT1L.it["The Exaltation of the Holy Cross"] = "Trionfo della Santa Croce, segno della nostra salvezza.";
SAINT1L.it["The Holy Guardian Angels"] = "Ogni persona ha un angelo che la custodisce e intercede per lei.";
SAINT1L.it["The Holy North American Martyrs"] = "Otto gesuiti martiri tra i popoli originari del Nordamerica.";
SAINT1L.it["The Immaculate Conception"] = "Maria fu concepita senza peccato originale per i meriti di Cristo.";
SAINT1L.it["The Immaculate Heart of Mary"] = "Il cuore puro di Maria, rifugio materno dei credenti.";
SAINT1L.it["The Nativity of Our Lord Jesus Christ"] = "Il Figlio di Dio nasce a Betlemme: Natale.";
SAINT1L.it["The Nativity of the Blessed Virgin"] = "Nasce Maria, la piena di grazia, aurora della salvezza.";
SAINT1L.it["The Presentation of Jesus in the Temple"] = "Maria e Giuseppe presentano il Bambino al tempio secondo la Legge.";
SAINT1L.it["The Presentation of the Blessed Virgin Mary"] = "La piccola Maria è offerta a Dio nel tempio.";
SAINT1L.it["The Seven Sorrows of the Blessed Virgin Mary"] = "I sette dolori che trafissero il cuore della Madre presso la croce.";
SAINT1L.it["The Visitation of the Blessed Virgin Mary"] = "Maria visita Elisabetta e canta il Magnificat.";
SAINT1L.it["Thomas"] = "Apostolo che dubitò e credette: «Signor mio e Dio mio!»; evangelizzò l’India.";
SAINT1L.it["Thomas Aquinas"] = "Domenicano che unì fede e ragione nella Somma Teologica; Dottore Angelico.";
SAINT1L.it["Thérèse of Lisieux"] = "Carmelitana francese della «piccola via»: amare Dio nelle piccole cose.";
SAINT1L.it["Timothy"] = "Discepolo di Paolo e primo vescovo di Efeso; morì martire.";
SAINT1L.it["Transfiguration of Our Lord"] = "Sul Tabor, Gesù mostra la sua gloria a Pietro, Giacomo e Giovanni.";
SAINT1L.it["Vincent de Paul"] = "Sacerdote francese padre dei poveri; fondò lazzaristi e Figlie della Carità.";
SAINT1L.la["Gregory the Great"] = "Papa qui liturgiam ordinavit, Angliam evangelizavit et de Scriptura scripsit.";
SAINT1L.la["Holy Innocents"] = "Infantes Bethlehemitici ab Herode occisi; primi martyres pro Christo.";
SAINT1L.la["Ignatius of Antioch"] = "Episcopus martyr Romae; eius litterae unitatem et Eucharistiam exaltant.";
SAINT1L.la["Ignatius of Loyola"] = "Miles vulneratus et conversus; Societatem Iesu et Exercitia fundavit.";
SAINT1L.la["Irenaeus"] = "Episcopus Lugdunensis qui haereses oppugnavit et fidem apostolicam defendit.";
SAINT1L.la["James the Greater"] = "Apostolus, primus martyr inter Duodecim; eius reliquiae Compostellae venerantur.";
SAINT1L.la["Jerome"] = "Bibliam in Latinum vertit (Vulgata); doctor Scripturae deditus.";
SAINT1L.la["Joachim"] = "Pater Virginis Mariae et sponsus sanctae Annae; vir pius.";
SAINT1L.la["John"] = "Discipulus dilectus, evangelista; Patmum relegatus Apocalypsim scripsit.";
SAINT1L.la["John Bosco"] = "Sacerdos Taurinensis qui iuvenes pauperes educavit et salesianos fundavit.";
SAINT1L.la["John Chrysostom"] = "Patriarcha Constantinopolitanus, os aureum praedicationis.";
SAINT1L.la["John Vianney"] = "Curatus Arsensis, humilis parochus confessioni et caritati deditus.";
SAINT1L.la["John of the Cross"] = "Mysticus carmelita cum Teresia Abulensi; noctem obscuram animae cecinit.";
SAINT1L.la["John the Baptist"] = "Praecursor Domini; Iesum in Iordane baptizavit et pro veritate mortuus est.";
SAINT1L.la["Josaphat"] = "Archiepiscopus martyr qui pro unitate christianorum orientalium laboravit.";
SAINT1L.la["Joseph"] = "Custos Iesu et Mariae; vir iustus, patronus patrum et operariorum.";
SAINT1L.la["Justin of Naplouse"] = "Philosophus conversus qui fidem scriptis defendit; martyr Romae.";
SAINT1L.la["Kateri Tekakwitha"] = "Iuvenis mohawk, Lilium Mohawkensium, fidelis Christo inter suos.";
SAINT1L.la["Lawrence"] = "Diaconus Romanus qui bona pauperibus distribuit ante martyrium.";
SAINT1L.la["Leo the Great"] = "Papa qui fidem in Christum definivit et Romam ab Attila verbo liberavit.";
SAINT1L.la["Lucy of Syracuse"] = "Iuvenis martyr Syracusana, symbolum puritatis et fortitudinis.";
SAINT1L.la["Luke"] = "Medicus et comes Pauli; tertium Evangelium et Actus scripsit.";
SAINT1L.la["Mark"] = "Secretarius Petri Romae; eius praedicationem in Evangelio conscripsit.";
SAINT1L.la["Martha"] = "Soror Mariae et Lazari, ministra Iesu et mulier magnae fidei.";
SAINT1L.la["Martin of Tours"] = "Miles qui chlamydem cum paupere divisit; episcopus et apostolus Galliae.";
SAINT1L.la["Mary Magdalen"] = "Testis crucis et prima Resurgentis; nuntiatrix ad apostolos.";
SAINT1L.la["Matthew"] = "Publicanus a Iesu vocatus; eius Evangelium Christum promissum praesentat.";
SAINT1L.la["Matthias"] = "Ab apostolis electus ut locum Iudae occuparet.";
SAINT1L.la["Maximilian Kolbe"] = "Franciscanus qui vitam pro patre familias in Auschwitz dedit.";
SAINT1L.la["Michael"] = "Archangelus princeps militiae caelestis; quis ut Deus?.";
SAINT1L.la["Monica"] = "Mater Augustini; lacrimis et oratione perseveranti eum conversum vidit.";
SAINT1L.la["Our Lady of Guadalupe"] = "Fuscula Tepeyacensis (1531), mater et signum unitatis Americae.";
SAINT1L.la["Our Lady of the Rosary"] = "Invocatio mariana Rosarii, memoria victoriae Lepantinae.";
SAINT1L.la["Peter"] = "Piscator Galilaeus, primus Papa; negavit, flevit et fratres confirmavit.";
SAINT1L.la["Peter Claver"] = "Iesuita qui centena milia servorum Carthagenae baptizavit et servivit.";
SAINT1L.la["Philip"] = "Apostolus qui Nathanaelem ad Iesum duxit et Patrem videre petiit.";
SAINT1L.la["Philip Neri"] = "Sacerdos Romanus laetus, amicus iuvenum; Oratorium fundavit.";
SAINT1L.la["Pius X"] = "Papa qui communionem frequentem fidelibus appropinquavit et modernismum oppugnavit.";
SAINT1L.la["Scholastica"] = "Soror Benedicti et abbatissa; vitam orationi consecravit.";
SAINT1L.la["Teresa of Avila"] = "Reformatrix Carmeli et doctrix; solus Deus sufficit.";
SAINT1L.la["The Assumption of the Blessed Virgin Mary"] = "Maria, in fine vitae, assumpta est in caelum corpore et anima.";
SAINT1L.la["The Baptism of Our Lord"] = "Iesus a Ioanne baptizatur: vitam publicam incipit.";
SAINT1L.la["The Conversion of Saint Paul"] = "Saulus, persecutor, Damasci cecidit et apostolus nationum factus est.";
SAINT1L.la["The Epiphany of Our Lord"] = "Magi Puerum adorant: Christus omnibus nationibus manifestatur.";
SAINT1L.la["The Exaltation of the Holy Cross"] = "Triumphus Sanctae Crucis, signum salutis nostrae.";
SAINT1L.la["The Holy Guardian Angels"] = "Unaquaeque persona angelum habet qui eam custodit et pro ea intercedit.";
SAINT1L.la["The Holy North American Martyrs"] = "Octo iesuitae martyres inter populos indigenas Americae Septentrionalis.";
SAINT1L.la["The Immaculate Conception"] = "Maria sine peccato originali concepta est meritis Christi.";
SAINT1L.la["The Immaculate Heart of Mary"] = "Cor purum Mariae, refugium maternum credentium.";
SAINT1L.la["The Nativity of Our Lord Jesus Christ"] = "Filius Dei Bethlehemi nascitur: Nativitas.";
SAINT1L.la["The Nativity of the Blessed Virgin"] = "Nascitur Maria, gratia plena, aurora salutis.";
SAINT1L.la["The Presentation of Jesus in the Temple"] = "Maria et Ioseph Puerum in templo secundum Legem praesentant.";
SAINT1L.la["The Presentation of the Blessed Virgin Mary"] = "Puella Maria Deo in templo offertur.";
SAINT1L.la["The Seven Sorrows of the Blessed Virgin Mary"] = "Septem dolores qui cor Matris iuxta crucem transfixerunt.";
SAINT1L.la["The Visitation of the Blessed Virgin Mary"] = "Maria Elisabeth visitat et Magnificat cantat.";
SAINT1L.la["Thomas"] = "Apostolus qui dubitavit et credidit: Dominus meus et Deus meus!; Indiam evangelizavit.";
SAINT1L.la["Thomas Aquinas"] = "Dominicanus qui fidem et rationem in Summa Theologica coniunxit; Doctor Angelicus.";
SAINT1L.la["Thérèse of Lisieux"] = "Carmelita Gallica parvae viae: Deum in parvis amare.";
SAINT1L.la["Timothy"] = "Discipulus Pauli et primus episcopus Ephesinus; martyr mortuus est.";
SAINT1L.la["Transfiguration of Our Lord"] = "In Thabor Iesus gloriam suam Petro, Iacobo et Ioanni ostendit.";
SAINT1L.la["Vincent de Paul"] = "Sacerdos Gallicus pater pauperum; lazaristas et Filias Caritatis fundavit.";
SAINT1L.fr = {"Agatha":"Martyre sicilienne du IIIe siècle, vénérée pour sa pureté et sa force dans la torture.","Agnes":"Martyre romaine de douze ans qui préféra mourir plutôt que renier le Christ.","All Saints":"Fête de tous les saints, connus et inconnus, et de la communion des saints.","Aloysius Gonzaga":"Jeune jésuite mort en soignant les pestiférés à Rome à 23 ans.","Alphonsus Liguori":"Évêque italien, fondateur des rédemptoristes et docteur de l’Église.","Ambrose":"Évêque de Milan, baptisa saint Augustin et défendit la foi par sa prédication.","Andrew":"Frère de Pierre et premier appelé ; évangélisa la Grèce et mourut sur une croix en X.","Annunciation of the Blessed Virgin Mary and the Incarnation of the Word of God":"L’annonce de l’ange Gabriel à Marie : le Fils de Dieu s’est fait homme.","Anthony of Padua":"Franciscain portugais, prédicateur thaumaturge ; on l’invoque pour les objets perdus.","Anthony of the Desert":"Égyptien du IIIe siècle, père du monachisme ; vécut de prière au désert.","Athanasius":"Évêque d’Alexandrie qui défendit la divinité du Christ contre l’arianisme.","Augustine":"Évêque d’Hippone ; après une jeunesse agitée il se convertit et fut lumière de l’Église.","Barnabas":"Compagnon de Paul dans ses voyages ; porta l’Évangile à Chypre et Antioche.","Bartholomew":"Apôtre (Nathanaël) qui prêcha jusqu’en Inde et en Arménie, où il fut martyrisé.","Basil the Great":"Évêque de Césarée, père du monachisme oriental et défenseur contre l’arianisme.","Benedict":"Patriarche du monachisme occidental ; sa Règle guide encore les monastères.","Bernard of Clairvaux":"Abbé cistercien du XIIe siècle, éloquent prédicateur et docteur de l’Église.","Bonaventure":"Franciscain, ministre général de l’Ordre et cardinal ; le Docteur Séraphique.","Boniface":"Missionnaire anglais, apôtre de l’Allemagne, martyr en confirmant.","Catherine of Siena":"Mystique et docteur qui conseilla les papes et ramena la papauté à Rome.","Cecilia":"Martyre romaine qui chanta Dieu dans son cœur ; patronne des musiciens.","Charles Borromeo":"Archevêque de Milan qui appliqua le concile de Trente par écoles et séminaires.","Clare of Assisi":"Première disciple de François ; fonda les clarisses et aima la pauvreté.","Cyprian":"Évêque de Carthage converti du paganisme ; martyr dans la persécution.","Cyril and Methodius":"Frères de Thessalonique, apôtres des Slaves ; créèrent leur alphabet.","Dominic":"Espagnol fondateur des dominicains, prédicateurs contre l’hérésie.","Elizabeth of Hungary":"Princesse qui servit pauvres et malades et construisit des hôpitaux.","Frances Xavier Cabrini":"Religieuse italo-américaine qui servit les immigrés aux États-Unis.","Francis Xavier":"Jésuite navarrais qui porta l’Évangile en Inde et au Japon.","Francis de Sales":"Évêque de Genève, maître de la douceur et de la vie dévote.","Francis of Assisi":"Le petit pauvre d’Assise qui épousa la pauvreté et chanta la création."};
SAINT1L.zh = {"Agatha":"三世纪西西里殉道者，以纯洁和受刑中的刚毅受敬礼。","Agnes":"十二岁的罗马殉道者，宁死不背弃基督。","All Saints":"诸圣瞻礼，纪念已知与未知的所有圣人及诸圣相通。","Aloysius Gonzaga":"年轻耶稣会士，23岁在罗马照顾鼠疫病人时去世。","Alphonsus Liguori":"意大利主教，赎主会创始人，教会圣师。","Ambrose":"米兰主教，给圣奥斯定付洗，以宣讲捍卫信仰。","Andrew":"伯多禄的兄弟，首召者；向希腊传福音，死于X形十字架。","Annunciation of the Blessed Virgin Mary and the Incarnation of the Word of God":"加俾额尔天使向玛利亚报喜：天主子降生成人。","Anthony of Padua":"葡萄牙方济各会士，行奇迹的宣讲者；遗失物品常求他帮助。","Anthony of the Desert":"三世纪埃及人，隐修之父，在沙漠中以祈祷生活。","Athanasius":"亚历山大里亚主教，面对亚略异端捍卫基督天主性。","Augustine":"希波主教；动荡青春后悔改，成为教会之光。","Barnabas":"保禄旅途中的同伴，把福音带到塞浦路斯和安提约基雅。","Bartholomew":"宗徒（纳塔乃耳），传教至印度和亚美尼亚，在那里殉道。","Basil the Great":"凯撒勒雅主教，东方隐修之父，反亚略异端的捍卫者。","Benedict":"西方隐修之祖；他的会规至今指引隐修院。","Bernard of Clairvaux":"十二世纪熙笃会院长，雄辩的宣讲者，教会圣师。","Bonaventure":"方济各会士，总会长、枢机；色拉芬博士。","Boniface":"英国传教士，德国的宗徒，在坚振时殉道。","Catherine of Siena":"神秘家、圣师，曾劝谏教宗，把教廷带回罗马。","Cecilia":"罗马殉道者，在心中歌颂天主；音乐家的主保。","Charles Borromeo":"米兰总主教，以学校和修院落实特伦托大公会议。","Clare of Assisi":"方济各的第一位追随者，创立加辣修女会，热爱神贫。","Cyprian":"迦太基主教，由异教悔改；在教难中殉道。","Cyril and Methodius":"得撒洛尼兄弟，斯拉夫人的宗徒；创造了他们的字母。","Dominic":"西班牙人，创立道明会，以宣讲对抗异端。","Elizabeth of Hungary":"公主，服侍穷人和病人，建造医院。","Frances Xavier Cabrini":"意裔美籍修女，在美国服务移民。","Francis Xavier":"纳瓦拉耶稣会士，把福音带到印度和日本。","Francis de Sales":"日内瓦主教，温良与虔诚生活的导师。","Francis of Assisi":"亚西西的小穷人，与贫穷结婚，歌颂受造界。"};
SAINT1L.fr["Gregory the Great"] = "Pape qui ordonna la liturgie, évangélisa l’Angleterre et écrivit sur l’Écriture.";
SAINT1L.fr["Holy Innocents"] = "Les enfants de Bethléem massacrés par Hérode ; premiers martyrs pour le Christ.";
SAINT1L.fr["Ignatius of Antioch"] = "Évêque martyr à Rome ; ses lettres exaltent l’unité et l’Eucharistie.";
SAINT1L.fr["Ignatius of Loyola"] = "Soldat blessé et converti ; fonda la Compagnie de Jésus et ses Exercices.";
SAINT1L.fr["Irenaeus"] = "Évêque de Lyon qui combattit les hérésies et défendit la foi apostolique.";
SAINT1L.fr["James the Greater"] = "Apôtre, premier martyr parmi les Douze ; ses restes sont vénérés à Compostelle.";
SAINT1L.fr["Jerome"] = "Traduisit la Bible en latin (Vulgate) ; docteur livré à l’Écriture.";
SAINT1L.fr["Joachim"] = "Père de la Vierge Marie et époux de sainte Anne ; homme pieux.";
SAINT1L.fr["John"] = "Le disciple bien-aimé, évangéliste ; exilé à Patmos, écrivit l’Apocalypse.";
SAINT1L.fr["John Bosco"] = "Prêtre turinois qui éduqua les jeunes pauvres et fonda les salésiens.";
SAINT1L.fr["John Chrysostom"] = "Patriarche de Constantinople, « bouche d’or » de la prédication.";
SAINT1L.fr["John Vianney"] = "Le curé d’Ars, humble pasteur livré à la confession et à la charité.";
SAINT1L.fr["John of the Cross"] = "Mystique carme avec Thérèse d’Avila ; chanta la nuit obscure de l’âme.";
SAINT1L.fr["John the Baptist"] = "Précurseur du Seigneur ; baptisa Jésus au Jourdain et mourut pour la vérité.";
SAINT1L.fr["Josaphat"] = "Archevêque martyr qui travailla pour l’unité des chrétiens orientaux.";
SAINT1L.fr["Joseph"] = "Gardien de Jésus et Marie ; homme juste, patron des pères et des travailleurs.";
SAINT1L.fr["Justin of Naplouse"] = "Philosophe converti qui défendit la foi par ses écrits ; martyr à Rome.";
SAINT1L.fr["Kateri Tekakwitha"] = "Jeune mohawk, le « Lis des Mohawks », fidèle au Christ parmi les siens.";
SAINT1L.fr["Lawrence"] = "Diacre romain qui distribua les biens aux pauvres avant son martyre.";
SAINT1L.fr["Leo the Great"] = "Pape qui définit la foi au Christ et délivra Rome d’Attila par sa parole.";
SAINT1L.fr["Lucy of Syracuse"] = "Jeune martyre sicilienne, symbole de pureté et de force.";
SAINT1L.fr["Luke"] = "Médecin et compagnon de Paul ; écrivit le troisième Évangile et les Actes.";
SAINT1L.fr["Mark"] = "Secrétaire de Pierre à Rome ; mit par écrit sa prédication dans son Évangile.";
SAINT1L.fr["Martha"] = "Sœur de Marie et Lazare, servante de Jésus et femme de grande foi.";
SAINT1L.fr["Martin of Tours"] = "Soldat qui partagea son manteau avec un pauvre ; évêque et apôtre de la Gaule.";
SAINT1L.fr["Mary Magdalen"] = "Témoin de la croix et première du Ressuscité ; annonciatrice aux apôtres.";
SAINT1L.fr["Matthew"] = "Publicain appelé par Jésus ; son Évangile présente le Christ promis.";
SAINT1L.fr["Matthias"] = "Élu par les apôtres pour occuper la place de Judas.";
SAINT1L.fr["Maximilian Kolbe"] = "Franciscain qui donna sa vie pour un père de famille à Auschwitz.";
SAINT1L.fr["Michael"] = "Archange prince de la milice céleste ; « qui comme Dieu ? »";
SAINT1L.fr["Monica"] = "Mère d’Augustin ; par larmes et prière persévérante elle le vit converti.";
SAINT1L.fr["Our Lady of Guadalupe"] = "La Morenita du Tepeyac (1531), mère et signe d’unité de l’Amérique.";
SAINT1L.fr["Our Lady of the Rosary"] = "Invocation mariale du Rosaire, mémoire de la victoire de Lépante.";
SAINT1L.fr["Peter"] = "Pêcheur de Galilée, premier Pape ; renia, pleura et confirma ses frères.";
SAINT1L.fr["Peter Claver"] = "Jésuite qui baptisa et servit des centaines de milliers d’esclaves à Carthagène.";
SAINT1L.fr["Philip"] = "Apôtre qui amena Nathanaël à Jésus et demanda à voir le Père.";
SAINT1L.fr["Philip Neri"] = "Prêtre romain joyeux, ami des jeunes ; fonda l’Oratoire.";
SAINT1L.fr["Pius X"] = "Pape qui rapprocha la communion fréquente des fidèles et combattit le modernisme.";
SAINT1L.fr["Scholastica"] = "Sœur de Benoît et abbesse ; consacra sa vie à la prière.";
SAINT1L.fr["Teresa of Avila"] = "Réformatrice du Carmel et docteur ; « Dieu seul suffit ».";
SAINT1L.fr["The Assumption of the Blessed Virgin Mary"] = "Marie, à la fin de sa vie, fut élevée au ciel en corps et en âme.";
SAINT1L.fr["The Baptism of Our Lord"] = "Jésus est baptisé par Jean : il commence sa vie publique.";
SAINT1L.fr["The Conversion of Saint Paul"] = "Saul, persécuteur, tomba à Damas et devint apôtre des nations.";
SAINT1L.fr["The Epiphany of Our Lord"] = "Les Mages adorent l’Enfant : le Christ se manifeste à toutes les nations.";
SAINT1L.fr["The Exaltation of the Holy Cross"] = "Triomphe de la Sainte Croix, signe de notre salut.";
SAINT1L.fr["The Holy Guardian Angels"] = "Chaque personne a un ange qui la garde et intercède pour elle.";
SAINT1L.fr["The Holy North American Martyrs"] = "Huit jésuites martyrs parmi les peuples autochtones d’Amérique du Nord.";
SAINT1L.fr["The Immaculate Conception"] = "Marie fut conçue sans péché originel par les mérites du Christ.";
SAINT1L.fr["The Immaculate Heart of Mary"] = "Le cœur pur de Marie, refuge maternel des croyants.";
SAINT1L.fr["The Nativity of Our Lord Jesus Christ"] = "Le Fils de Dieu naît à Bethléem : Noël.";
SAINT1L.fr["The Nativity of the Blessed Virgin"] = "Naît Marie, la pleine de grâce, aurore du salut.";
SAINT1L.fr["The Presentation of Jesus in the Temple"] = "Marie et Joseph présentent l’Enfant au temple selon la Loi.";
SAINT1L.fr["The Presentation of the Blessed Virgin Mary"] = "La petite Marie est offerte à Dieu au temple.";
SAINT1L.fr["The Seven Sorrows of the Blessed Virgin Mary"] = "Les sept douleurs qui transpercèrent le cœur de la Mère près de la croix.";
SAINT1L.fr["The Visitation of the Blessed Virgin Mary"] = "Marie visite Élisabeth et chante le Magnificat.";
SAINT1L.fr["Thomas"] = "Apôtre qui douta et crut : « Mon Seigneur et mon Dieu ! » ; évangélisa l’Inde.";
SAINT1L.fr["Thomas Aquinas"] = "Dominicain qui unit foi et raison dans la Somme Théologique ; Docteur Angélique.";
SAINT1L.fr["Thérèse of Lisieux"] = "Carmélite française de la « petite voie » : aimer Dieu dans le petit.";
SAINT1L.fr["Timothy"] = "Disciple de Paul et premier évêque d’Éphèse ; mourut martyr.";
SAINT1L.fr["Transfiguration of Our Lord"] = "Sur le Thabor, Jésus montre sa gloire à Pierre, Jacques et Jean.";
SAINT1L.fr["Vincent de Paul"] = "Prêtre français père des pauvres ; fonda lazaristes et Filles de la Charité.";
SAINT1L.zh["Gregory the Great"] = "教宗，整顿礼仪，向英格兰传教，著述阐释圣经。";
SAINT1L.zh["Holy Innocents"] = "被黑落德杀害的白冷婴孩；为基督的首批殉道者。";
SAINT1L.zh["Ignatius of Antioch"] = "在罗马殉道的主教；书信颂扬合一与圣体。";
SAINT1L.zh["Ignatius of Loyola"] = "受伤悔改的军人；创立耶稣会及其神操。";
SAINT1L.zh["Irenaeus"] = "里昂主教，驳斥异端，捍卫宗徒信仰。";
SAINT1L.zh["James the Greater"] = "宗徒，十二位中首位殉道者；遗骸受敬于孔波斯特拉。";
SAINT1L.zh["Jerome"] = "把圣经译为拉丁文（武加大）；献身圣经的圣师。";
SAINT1L.zh["Joachim"] = "圣母玛利亚之父，圣亚纳之夫；虔诚之人。";
SAINT1L.zh["John"] = "爱徒，圣史；被放逐至帕特摩，著默示录。";
SAINT1L.zh["John Bosco"] = "都灵司铎，教育贫苦青年，创立慈幼会。";
SAINT1L.zh["John Chrysostom"] = "君士坦丁堡宗主教，宣讲的“金口”。";
SAINT1L.zh["John Vianney"] = "亚尔斯本堂神父，谦逊，献身告解与爱德。";
SAINT1L.zh["John of the Cross"] = "与亚维拉德兰贞女同道的加尔默罗神秘家；歌咏灵魂的黑夜。";
SAINT1L.zh["John the Baptist"] = "主的前驱；在约旦河给耶稣付洗，为真理而死。";
SAINT1L.zh["Josaphat"] = "为东方基督徒合一工作的殉道总主教。";
SAINT1L.zh["Joseph"] = "耶稣与玛利亚的护守；义人，父亲与工人的主保。";
SAINT1L.zh["Justin of Naplouse"] = "悔改的哲学家，以著述捍卫信仰；在罗马殉道。";
SAINT1L.zh["Kateri Tekakwitha"] = "莫霍克少女，“莫霍克百合”，在族人中忠于基督。";
SAINT1L.zh["Lawrence"] = "罗马执事，殉道前把财产分给穷人。";
SAINT1L.zh["Leo the Great"] = "教宗，界定基督信仰，以言辞使罗马免于阿提拉之手。";
SAINT1L.zh["Lucy of Syracuse"] = "叙拉古少女殉道者，纯洁与刚毅的象征。";
SAINT1L.zh["Luke"] = "医生，保禄的同伴；著第三福音与宗徒大事录。";
SAINT1L.zh["Mark"] = "在罗马任伯多禄的秘书；把他的宣讲写成福音。";
SAINT1L.zh["Martha"] = "玛利亚与拉匝禄的姐妹，服侍耶稣，信德深厚。";
SAINT1L.zh["Martin of Tours"] = "把斗篷分给穷人的军人；主教，高卢的宗徒。";
SAINT1L.zh["Mary Magdalen"] = "十字架的见证人，复活主的首位见证人；向宗徒们报喜。";
SAINT1L.zh["Matthew"] = "蒙耶稣召叫的税吏；福音呈现预许的基督。";
SAINT1L.zh["Matthias"] = "宗徒们选出顶替犹达斯者。";
SAINT1L.zh["Maximilian Kolbe"] = "方济各会士，在奥斯维辛为一位父亲舍生。";
SAINT1L.zh["Michael"] = "总领天使，天军统帅；“谁如天主？”。";
SAINT1L.zh["Monica"] = "奥斯定的母亲；以眼泪和恒心祈祷，终见子悔改。";
SAINT1L.zh["Our Lady of Guadalupe"] = "特佩亚克的黑圣母（1531），美洲的母亲与合一标记。";
SAINT1L.zh["Our Lady of the Rosary"] = "玫瑰圣母称号，纪念勒班陀胜利。";
SAINT1L.zh["Peter"] = "加里肋亚渔夫，首任教宗；否认过、哭过，坚固了弟兄。";
SAINT1L.zh["Peter Claver"] = "耶稣会士，在卡塔赫纳给数十万奴隶付洗、服务他们。";
SAINT1L.zh["Philip"] = "把纳塔乃耳带到耶稣前的宗徒，曾求见圣父。";
SAINT1L.zh["Philip Neri"] = "罗马喜乐的司铎，青年之友；创立祈祷会。";
SAINT1L.zh["Pius X"] = "使频繁领圣体走近信友的教宗；驳斥现代主义。";
SAINT1L.zh["Scholastica"] = "本笃的妹妹，女隐修院院长；一生献于祈祷。";
SAINT1L.zh["Teresa of Avila"] = "加尔默罗改革者、圣师；“唯天主足矣”。";
SAINT1L.zh["The Assumption of the Blessed Virgin Mary"] = "玛利亚尘世生命终结时，肉身灵魂被提升天。";
SAINT1L.zh["The Baptism of Our Lord"] = "耶稣受若翰洗礼：开始公开生活。";
SAINT1L.zh["The Conversion of Saint Paul"] = "迫害者扫禄在大马士革跌倒，成为万民的宗徒。";
SAINT1L.zh["The Epiphany of Our Lord"] = "贤士朝拜圣婴：基督向万民显现。";
SAINT1L.zh["The Exaltation of the Holy Cross"] = "光荣十字圣架，我们救恩的标记。";
SAINT1L.zh["The Holy Guardian Angels"] = "每人皆有护守天使守护并为其代祷。";
SAINT1L.zh["The Holy North American Martyrs"] = "八位耶稣会士在北美原住民中殉道。";
SAINT1L.zh["The Immaculate Conception"] = "玛利亚因基督功绩，始胎无染原罪。";
SAINT1L.zh["The Immaculate Heart of Mary"] = "玛利亚的无玷之心，信友的慈母避难所。";
SAINT1L.zh["The Nativity of Our Lord Jesus Christ"] = "天主子诞生于白冷：圣诞。";
SAINT1L.zh["The Nativity of the Blessed Virgin"] = "玛利亚诞生，满被圣宠，救恩的曙光。";
SAINT1L.zh["The Presentation of Jesus in the Temple"] = "玛利亚与若瑟按法律把圣婴献于圣殿。";
SAINT1L.zh["The Presentation of the Blessed Virgin Mary"] = "小玛利亚被奉献于圣殿归于天主。";
SAINT1L.zh["The Seven Sorrows of the Blessed Virgin Mary"] = "十字架旁刺透圣母之心的七苦。";
SAINT1L.zh["The Visitation of the Blessed Virgin Mary"] = "玛利亚探访依撒伯尔，歌咏谢主曲。";
SAINT1L.zh["Thomas"] = "怀疑而后信的宗徒：“我主！我天主！”；向印度传福音。";
SAINT1L.zh["Thomas Aquinas"] = "道明会士，在神学大全中结合信德与理性；天使圣师。";
SAINT1L.zh["Thérèse of Lisieux"] = "法国加尔默罗修女，“小路”：在小事上爱天主。";
SAINT1L.zh["Timothy"] = "保禄的门徒，厄弗所首任主教；殉道。";
SAINT1L.zh["Transfiguration of Our Lord"] = "在大博尔山，耶稣向伯多禄、雅各伯、若望显圣容。";
SAINT1L.zh["Vincent de Paul"] = "法国司铎，穷人之父；创立遣使会与仁爱修女会。";
SAINT1L.tl = {"Agatha":"Martir na taga-Sicilia noong ika-3 siglo, pinararangalan sa kalinisan at katatagan sa pagpapahirap.","Agnes":"Martir na taga-Roma na labindalawang taong gulang na mas piniling mamatay kaysa talikuran si Cristo.","All Saints":"Kapistahan ng lahat ng santo, kilala at di-kilala, at ng pakikisama ng mga banal.","Aloysius Gonzaga":"Batang Heswita na namatay sa pag-aalaga ng mga may salot sa Roma sa edad na 23.","Alphonsus Liguori":"Obispong Italyano, tagapagtatag ng mga Redentorista at pantas ng Simbahan.","Ambrose":"Obispo ng Milan, bininyagan si San Agustin at ipinagtanggol ang pananampalataya sa pangangaral.","Andrew":"Kapatid ni Pedro at unang tinawag; ipinangaral ang Ebanghelyo sa Grecia at namatay sa krus na pa-ekis.","Annunciation of the Blessed Virgin Mary and the Incarnation of the Word of God":"Ang balita ng anghel Gabriel kay Maria: ang Anak ng Diyos ay naging tao.","Anthony of Padua":"Pransiskanong Portuges, milagrosong mangangaral; hinihingan ng tulong sa mga nawawalang bagay.","Anthony of the Desert":"Ehipsiyo noong ika-3 siglo, ama ng monastisismo; nabuhay sa panalangin sa disyerto.","Athanasius":"Obispo ng Alexandria na ipinagtanggol ang pagka-Diyos ni Cristo laban sa Arianismo.","Augustine":"Obispo ng Hipona; pagkatapos ng magulong kabataan ay nagbalik-loob at naging ilaw ng Simbahan.","Barnabas":"Kasama ni Pablo sa mga paglalakbay; dinala ang Ebanghelyo sa Chipre at Antioquia.","Bartholomew":"Apostol (Natanael) na nangaral hanggang India at Armenia, kung saan siya naging martir.","Basil the Great":"Obispo ng Cesarea, ama ng silangang monastisismo at tagapagtanggol laban sa Arianismo.","Benedict":"Patriarka ng kanluraning monastisismo; ang kanyang Tuntunin ay gumagabay pa rin sa mga monasteryo.","Bernard of Clairvaux":"Abad na Cisterciense noong ika-12 siglo, mahusay na mangangaral at pantas ng Simbahan.","Bonaventure":"Pransiskano, pangkalahatang ministro ng Orden at kardinal; ang Doktor Serapiko.","Boniface":"Ingles na misyonero, apostol ng Alemania, martir habang nagkukumpil.","Catherine of Siena":"Mistika at pantas na nagpayo sa mga papa at nagbalik ng papado sa Roma.","Cecilia":"Martir na taga-Roma na umawit sa Diyos sa kanyang puso; patrona ng mga musikero.","Charles Borromeo":"Arsobispo ng Milan na naglapat ng Konsilyo ng Trento sa pamamagitan ng mga paaralan at seminaryo.","Clare of Assisi":"Unang tagasunod ni Francisco; itinatag ang mga Klarisa at minahal ang kahirapan.","Cyprian":"Obispo ng Cartago na nagbalik-loob mula sa paganismo; martir sa pag-uusig.","Cyril and Methodius":"Magkapatid na taga-Tesalonica, mga apostol ng mga Eslabo; lumikha ng kanilang alpabeto.","Dominic":"Kastilang tagapagtatag ng mga Dominikano, mga mangangaral laban sa erehiya.","Elizabeth of Hungary":"Prinsesang naglingkod sa mahihirap at maysakit at nagtayo ng mga ospital.","Frances Xavier Cabrini":"Relihiyosang Italyano-Amerikano na naglingkod sa mga imigrante sa Estados Unidos.","Francis Xavier":"Heswitang taga-Navarra na nagdala ng Ebanghelyo sa India at Hapon.","Francis de Sales":"Obispo ng Geneva, guro ng kaamuan at ng debotong buhay.","Francis of Assisi":"Ang abang si Francisco ng Asis na ikinasal sa kahirapan at umawit sa sangnilikha."};
SAINT1L.vi = {"Agatha":"Thánh nữ tử đạo Sicilia thế kỷ III, được tôn kính vì đức khiết tịnh và kiên cường trước tra tấn.","Agnes":"Thánh nữ tử đạo Roma mười hai tuổi, thà chết còn hơn chối bỏ Chúa Kitô.","All Saints":"Lễ các thánh nam nữ, known và unknown, và sự hiệp thông các thánh.","Aloysius Gonzaga":"Tu sĩ Dòng Tên trẻ qua đời khi chăm sóc bệnh nhân dịch hạch ở Roma lúc 23 tuổi.","Alphonsus Liguori":"Giám mục Italia, sáng lập Dòng Chúa Cứu Thế và là tiến sĩ Hội Thánh.","Ambrose":"Giám mục Milan, đã rửa tội cho thánh Augustinô và bảo vệ đức tin bằng giảng thuyết.","Andrew":"Em thánh Phêrô và là người được gọi đầu tiên; đã rao giảng Tin Mừng tại Hy Lạp và chịu chết trên thập giá hình chữ X.","Annunciation of the Blessed Virgin Mary and the Incarnation of the Word of God":"Lời thiên thần Gabriel truyền cho Đức Mẹ: Con Thiên Chúa đã làm người.","Anthony of Padua":"Tu sĩ Phanxicô người Bồ Đào Nha, nhà giảng thuyết hay làm phép lạ; người ta cầu ngài giúp tìm đồ thất lạc.","Anthony of the Desert":"Người Ai Cập thế kỷ III, tổ phụ đời đan tu; sống bằng cầu nguyện trong sa mạc.","Athanasius":"Giám mục Alexandria đã bảo vệ thiên tính Chúa Kitô chống lại lạc thuyết Ario.","Augustine":"Giám mục Hippo; sau tuổi trẻ bất an đã trở lại và thành ánh sáng Hội Thánh.","Barnabas":"Bạn đồng hành của thánh Phaolô trong các chuyến đi; đã đem Tin Mừng đến Chipre và Antiochia.","Bartholomew":"Tông đồ (Nathanael) đã giảng tới Ấn Độ và Armenia, nơi ngài chịu tử đạo.","Basil the Great":"Giám mục Caesarea, tổ phụ đan tu Đông phương và là người bảo vệ chống lạc thuyết Ario.","Benedict":"Tổ phụ đan tu Tây phương; Tu luật của ngài vẫn hướng dẫn các đan viện.","Bernard of Clairvaux":"Viện phụ Xitô thế kỷ XII, nhà giảng thuyết hùng hồn và tiến sĩ Hội Thánh.","Bonaventure":"Tu sĩ Phanxicô, bề trên tổng quyền Dòng và hồng y; Tiến sĩ Seraphim.","Boniface":"Nhà truyền giáo người Anh, tông đồ nước Đức, tử đạo khi đang ban bí tích Thêm Sức.","Catherine of Siena":"Nhà thần bí và tiến sĩ đã cố vấn cho các giáo hoàng và đưa giáo triều về Roma.","Cecilia":"Thánh nữ tử đạo Roma đã ca hát Chúa trong lòng; bổn mạng các nhạc sĩ.","Charles Borromeo":"Tổng giám mục Milan đã áp dụng Công đồng Trento bằng trường học và chủng viện.","Clare of Assisi":"Người đầu tiên theo thánh Phanxicô; sáng lập Dòng Chị Em Khó Nghèo và yêu mến khó nghèo.","Cyprian":"Giám mục Carthage trở lại từ ngoại giáo; tử đạo trong cuộc bách hại.","Cyril and Methodius":"Hai anh em Thessalonica, tông đồ người Slav; đã sáng tạo mẫu tự cho họ.","Dominic":"Người Tây Ban Nha sáng lập Dòng Đa Minh, các nhà giảng thuyết chống lạc giáo.","Elizabeth of Hungary":"Công chúa đã phục vụ người nghèo và bệnh nhân, xây bệnh viện.","Frances Xavier Cabrini":"Nữ tu Italia-Hoa Kỳ đã phục vụ người nhập cư tại Hoa Kỳ.","Francis Xavier":"Tu sĩ Dòng Tên người Navarra đã đem Tin Mừng đến Ấn Độ và Nhật Bản.","Francis de Sales":"Giám mục Geneva, bậc thầy về hiền lành và đời sống đạo đức.","Francis of Assisi":"Người nghèo thành Assisi đã kết hôn với đức khó nghèo và ca ngợi thụ tạo."};
SAINT1L.vi["All Saints"] = "Lễ các thánh nam nữ, những vị được biết đến và không được biết đến, và sự hiệp thông các thánh.";
SAINT1L.tl["Gregory the Great"] = "Papang nag-ayos ng liturhiya, nag-Ebanghelyo sa Inglaterra at sumulat tungkol sa Kasulatan.";
SAINT1L.tl["Holy Innocents"] = "Mga bata ng Belen na pinatay ni Herodes; mga unang martir para kay Cristo.";
SAINT1L.tl["Ignatius of Antioch"] = "Obispong martir sa Roma; ang kanyang mga liham ay nagdakila sa pagkakaisa at Eukaristiya.";
SAINT1L.tl["Ignatius of Loyola"] = "Sundalong nasugatan at nagbalik-loob; itinatag ang Kapisanan ni Jesus at ang mga Pagsasanay.";
SAINT1L.tl["Irenaeus"] = "Obispo ng Lyon na lumaban sa mga erehiya at ipinagtanggol ang pananampalatayang apostoliko.";
SAINT1L.tl["James the Greater"] = "Apostol, unang martir sa Labindalawa; ang kanyang mga labi ay pinararangalan sa Compostela.";
SAINT1L.tl["Jerome"] = "Isinalin ang Biblia sa Latin (Vulgata); pantas na nakatalaga sa Kasulatan.";
SAINT1L.tl["Joachim"] = "Ama ng Birheng Maria at esposo ni Santa Ana; taong madasalin.";
SAINT1L.tl["John"] = "Ang minamahal na alagad, ebanghelista; ipinatapon sa Patmos, isinulat ang Apocalipsis.";
SAINT1L.tl["John Bosco"] = "Paring taga-Turin na nag-aruga sa mahihirap na kabataan at itinatag ang mga Salesyano.";
SAINT1L.tl["John Chrysostom"] = "Patriarka ng Constantinopla, gintong bibig ng pangangaral.";
SAINT1L.tl["John Vianney"] = "Ang kura ng Ars, mapagkumbabang paring nakatalaga sa kumpisal at kawanggawa.";
SAINT1L.tl["John of the Cross"] = "Mistikong Karmelita kasama ni Teresa ng Avila; umawit ng madilim na gabi ng kaluluwa.";
SAINT1L.tl["John the Baptist"] = "Tagapagpauna ng Panginoon; bininyagan si Jesus sa Jordan at namatay para sa katotohanan.";
SAINT1L.tl["Josaphat"] = "Arsobispong martir na nagtrabaho para sa pagkakaisa ng mga silangang Kristiyano.";
SAINT1L.tl["Joseph"] = "Tagapag-ingat nina Jesus at Maria; taong matuwid, patron ng mga ama at manggagawa.";
SAINT1L.tl["Justin of Naplouse"] = "Pilosopong nagbalik-loob na ipinagtanggol ang pananampalataya sa mga sinulat; martir sa Roma.";
SAINT1L.tl["Kateri Tekakwitha"] = "Batang Mohawk, ang Liryo ng mga Mohawk, tapat kay Cristo sa kanyang mga kababayan.";
SAINT1L.tl["Lawrence"] = "Diakonong taga-Roma na namahagi ng mga ari-arian sa mahihirap bago ang pagkamartir.";
SAINT1L.tl["Leo the Great"] = "Papang nagpaliwanag ng pananampalataya kay Cristo at nagligtas sa Roma mula kay Atila sa salita.";
SAINT1L.tl["Lucy of Syracuse"] = "Batang martir na taga-Siracusa, sagisag ng kalinisan at katatagan.";
SAINT1L.tl["Luke"] = "Manggagamot at kasama ni Pablo; isinulat ang ikatlong Ebanghelyo at ang mga Gawa.";
SAINT1L.tl["Mark"] = "Kalihim ni Pedro sa Roma; isinulat ang kanyang pangangaral sa Ebanghelyo.";
SAINT1L.tl["Martha"] = "Kapatid nina Maria at Lazaro, lingkod ni Jesus at babaeng may malaking pananampalataya.";
SAINT1L.tl["Martin of Tours"] = "Sundalong humati ng kanyang kapa para sa mahirap; obispo at apostol ng Galia.";
SAINT1L.tl["Mary Magdalen"] = "Saksi ng krus at una ng Muling Nabuhay; tagapagbalita sa mga apostol.";
SAINT1L.tl["Matthew"] = "Maniningil ng buwis na tinawag ni Jesus; ang kanyang Ebanghelyo ay nagpakilala kay Cristong ipinangako.";
SAINT1L.tl["Matthias"] = "Hinirang ng mga apostol upang punan ang lugar ni Judas.";
SAINT1L.tl["Maximilian Kolbe"] = "Pransiskanong nag-alay ng buhay para sa isang ama ng pamilya sa Auschwitz.";
SAINT1L.tl["Michael"] = "Arkanghel na prinsipe ng makalangit na hukbo; sino ang gaya ng Diyos?.";
SAINT1L.tl["Monica"] = "Ina ni Agustin; sa luha at matiyagang panalangin ay nakita niya itong nagbalik-loob.";
SAINT1L.tl["Our Lady of Guadalupe"] = "Ang Morenita ng Tepeyac (1531), ina at tanda ng pagkakaisa ng Amerika.";
SAINT1L.tl["Our Lady of the Rosary"] = "Marianong debosyon ng Rosaryo, alaala ng tagumpay sa Lepanto.";
SAINT1L.tl["Peter"] = "Mangingisdang taga-Galilea, unang Papa; nagkaila, umiyak at nagpatibay sa mga kapatid.";
SAINT1L.tl["Peter Claver"] = "Heswitang nagbinyag at naglingkod sa daan-daang libong alipin sa Cartagena.";
SAINT1L.tl["Philip"] = "Apostol na nagdala kay Natanael kay Jesus at humiling na makita ang Ama.";
SAINT1L.tl["Philip Neri"] = "Masayahing paring taga-Roma, kaibigan ng kabataan; itinatag ang Oratoryo.";
SAINT1L.tl["Pius X"] = "Papang nagpalapit ng madalas na pakikinabang sa mga mananampalataya at lumaban sa modernismo.";
SAINT1L.tl["Scholastica"] = "Kapatid ni Benito at abadesa; inialay ang buhay sa panalangin.";
SAINT1L.tl["Teresa of Avila"] = "Repormadora ng Carmelo at pantas; ang Diyos lamang ay sapat.";
SAINT1L.tl["The Assumption of the Blessed Virgin Mary"] = "Si Maria, sa katapusan ng kanyang buhay, ay iniakyat sa langit katawan at kaluluwa.";
SAINT1L.tl["The Baptism of Our Lord"] = "Bininyagan si Jesus ni Juan: nagsisimula ang kanyang pampublikong buhay.";
SAINT1L.tl["The Conversion of Saint Paul"] = "Si Saulo, mang-uusig, ay bumagsak sa Damasco at naging apostol ng mga bansa.";
SAINT1L.tl["The Epiphany of Our Lord"] = "Sinamba ng mga Mago ang Bata: nahayag si Cristo sa lahat ng bansa.";
SAINT1L.tl["The Exaltation of the Holy Cross"] = "Tagumpay ng Santa Cruz, tanda ng ating kaligtasan.";
SAINT1L.tl["The Holy Guardian Angels"] = "Bawat tao ay may anghel na nagbabantay at namamagitan para sa kanya.";
SAINT1L.tl["The Holy North American Martyrs"] = "Walong Heswitang martir sa mga katutubong bayan ng Hilagang Amerika.";
SAINT1L.tl["The Immaculate Conception"] = "Si Maria ay ipinaglihing walang orihinal na kasalanan dahil sa mga merito ni Cristo.";
SAINT1L.tl["The Immaculate Heart of Mary"] = "Ang dalisay na puso ni Maria, kanlungan ng mga mananampalataya.";
SAINT1L.tl["The Nativity of Our Lord Jesus Christ"] = "Isinilang ang Anak ng Diyos sa Belen: Pasko.";
SAINT1L.tl["The Nativity of the Blessed Virgin"] = "Isinilang si Maria, ang puno ng grasya, bukang-liwayway ng kaligtasan.";
SAINT1L.tl["The Presentation of Jesus in the Temple"] = "Iniharap nina Maria at Jose ang Bata sa templo ayon sa Kautusan.";
SAINT1L.tl["The Presentation of the Blessed Virgin Mary"] = "Ang batang si Maria ay inihandog sa Diyos sa templo.";
SAINT1L.tl["The Seven Sorrows of the Blessed Virgin Mary"] = "Ang pitong dalamhating tumagos sa puso ng Ina sa tabi ng krus.";
SAINT1L.tl["The Visitation of the Blessed Virgin Mary"] = "Dinalaw ni Maria si Isabel at inawit ang Magnificat.";
SAINT1L.tl["Thomas"] = "Apostol na nag-alinlangan at naniwala: Panginoon ko at Diyos ko!; ipinangaral ang Ebanghelyo sa India.";
SAINT1L.tl["Thomas Aquinas"] = "Dominikanong nag-ugnay ng pananampalataya at katwiran sa Suma Teologica; Doktor Angeliko.";
SAINT1L.tl["Thérèse of Lisieux"] = "Pranses na Karmelita ng munting landas: ang mahalin ang Diyos sa maliliit.";
SAINT1L.tl["Timothy"] = "Alagad ni Pablo at unang obispo ng Efeso; namatay na martir.";
SAINT1L.tl["Transfiguration of Our Lord"] = "Sa Tabor, ipinakita ni Jesus ang kanyang kaluwalhatian kina Pedro, Santiago at Juan.";
SAINT1L.tl["Vincent de Paul"] = "Pranses na pari, ama ng mahihirap; itinatag ang mga Paulino at mga Anak ng Kawanggawa.";
SAINT1L.vi["Gregory the Great"] = "Đức giáo hoàng đã chấn chỉnh phụng vụ, rao giảng Tin Mừng tại Anh và viết về Kinh Thánh.";
SAINT1L.vi["Holy Innocents"] = "Các hài nhi Bêlem bị Hêrôđê sát hại; các thánh tử đạo đầu tiên vì Chúa Kitô.";
SAINT1L.vi["Ignatius of Antioch"] = "Giám mục tử đạo tại Roma; thư của ngài đề cao sự hiệp nhất và Thánh Thể.";
SAINT1L.vi["Ignatius of Loyola"] = "Người lính bị thương rồi trở lại; sáng lập Dòng Tên và Linh Thao.";
SAINT1L.vi["Irenaeus"] = "Giám mục Lyon đã chống lại các lạc thuyết và bảo vệ đức tin tông truyền.";
SAINT1L.vi["James the Greater"] = "Tông đồ, vị tử đạo đầu tiên trong Nhóm Mười Hai; hài cốt ngài được tôn kính tại Compostela.";
SAINT1L.vi["Jerome"] = "Đã dịch Kinh Thánh sang tiếng Latinh (Vulgata); tiến sĩ dấn thân cho Kinh Thánh.";
SAINT1L.vi["Joachim"] = "Thân phụ Đức Trinh Nữ Maria và là bạn thánh Anna; người đạo đức.";
SAINT1L.vi["John"] = "Người môn đệ được yêu, tác giả Tin Mừng; bị đày ra Patmos, đã viết Khải Huyền.";
SAINT1L.vi["John Bosco"] = "Linh mục Torino đã giáo dục thanh thiếu niên nghèo và sáng lập Dòng Salêdiêng.";
SAINT1L.vi["John Chrysostom"] = "Thượng phụ Constantinople, miệng vàng của việc giảng thuyết.";
SAINT1L.vi["John Vianney"] = "Cha xứ Ars, vị mục tử khiêm nhường dấn thân cho tòa giải tội và bác ái.";
SAINT1L.vi["John of the Cross"] = "Nhà thần bí Dòng Cát Minh với thánh Têrêsa Avila; đã ca ngợi đêm tối của linh hồn.";
SAINT1L.vi["John the Baptist"] = "Vị Tiền Hô của Chúa; đã rửa tội cho Chúa Giêsu tại sông Giođan và chết vì chân lý.";
SAINT1L.vi["Josaphat"] = "Tổng giám mục tử đạo đã làm việc cho sự hiệp nhất các Kitô hữu Đông phương.";
SAINT1L.vi["Joseph"] = "Đấng giữ gìn Chúa Giêsu và Đức Mẹ; người công chính, bổn mạng các người cha và công nhân.";
SAINT1L.vi["Justin of Naplouse"] = "Triết gia trở lại đã bảo vệ đức tin bằng văn phẩm; tử đạo tại Roma.";
SAINT1L.vi["Kateri Tekakwitha"] = "Thiếu nữ Mohawk, Bông Huệ của người Mohawk, trung thành với Chúa Kitô giữa đồng bào.";
SAINT1L.vi["Lawrence"] = "Phó tế Roma đã phân phát của cải cho người nghèo trước khi chịu tử đạo.";
SAINT1L.vi["Leo the Great"] = "Đức giáo hoàng đã xác định đức tin vào Chúa Kitô và cứu Roma khỏi Attila bằng lời nói.";
SAINT1L.vi["Lucy of Syracuse"] = "Thánh nữ tử đạo trẻ thành Syracuse, biểu tượng của khiết tịnh và kiên cường.";
SAINT1L.vi["Luke"] = "Thầy thuốc và bạn đồng hành của thánh Phaolô; đã viết Tin Mừng thứ ba và sách Công vụ.";
SAINT1L.vi["Mark"] = "Thư ký của thánh Phêrô tại Roma; đã ghi lại lời giảng của ngài trong Tin Mừng.";
SAINT1L.vi["Martha"] = "Chị của Maria và Lazarô, người phục vụ Chúa Giêsu và có đức tin lớn.";
SAINT1L.vi["Martin of Tours"] = "Người lính đã chia áo choàng cho người nghèo; giám mục và tông đồ xứ Gaul.";
SAINT1L.vi["Mary Magdalen"] = "Chứng nhân thập giá và là người đầu tiên của Đấng Phục Sinh; sứ giả loan báo cho các tông đồ.";
SAINT1L.vi["Matthew"] = "Người thu thuế được Chúa Giêsu gọi; Tin Mừng của ngài trình bày Chúa Kitô đã được hứa.";
SAINT1L.vi["Matthias"] = "Được các tông đồ chọn để thay chỗ Giuđa.";
SAINT1L.vi["Maximilian Kolbe"] = "Tu sĩ Phanxicô đã hiến mạng vì một người cha gia đình tại Auschwitz.";
SAINT1L.vi["Michael"] = "Tổng lãnh thiên thần, hoàng tử các đạo binh trên trời; ai bằng Thiên Chúa?.";
SAINT1L.vi["Monica"] = "Mẹ thánh Augustinô; bằng nước mắt và cầu nguyện kiên trì đã thấy con trở lại.";
SAINT1L.vi["Our Lady of Guadalupe"] = "Đức Mẹ da nâu Tepeyac (1531), mẹ và dấu chỉ hiệp nhất châu Mỹ.";
SAINT1L.vi["Our Lady of the Rosary"] = "Tước hiệu Mân Côi của Đức Mẹ, nhớ chiến thắng Lepanto.";
SAINT1L.vi["Peter"] = "Ngư phủ Galilê, giáo hoàng đầu tiên; đã chối, đã khóc và đã củng cố anh em.";
SAINT1L.vi["Peter Claver"] = "Tu sĩ Dòng Tên đã rửa tội và phục vụ hàng trăm nghìn nô lệ tại Cartagena.";
SAINT1L.vi["Philip"] = "Tông đồ đã đưa Nathanael đến với Chúa Giêsu và xin được thấy Chúa Cha.";
SAINT1L.vi["Philip Neri"] = "Linh mục Roma vui tươi, bạn của giới trẻ; sáng lập Dòng Oratorio.";
SAINT1L.vi["Pius X"] = "Đức giáo hoàng đã đưa việc rước lễ thường xuyên đến gần tín hữu và chống thuyết hiện đại.";
SAINT1L.vi["Scholastica"] = "Em thánh Bênêđictô và là viện mẫu; dâng đời mình cho cầu nguyện.";
SAINT1L.vi["Teresa of Avila"] = "Nhà cải cách Dòng Cát Minh và tiến sĩ; một mình Chúa là đủ.";
SAINT1L.vi["The Assumption of the Blessed Virgin Mary"] = "Đức Mẹ, lúc cuối đời, đã được đưa lên trời cả hồn lẫn xác.";
SAINT1L.vi["The Baptism of Our Lord"] = "Chúa Giêsu chịu ông Gioan làm phép rửa: bắt đầu đời sống công khai.";
SAINT1L.vi["The Conversion of Saint Paul"] = "Saolô, kẻ bắt đạo, ngã xuống tại Đamas và thành tông đồ các dân tộc.";
SAINT1L.vi["The Epiphany of Our Lord"] = "Các Đạo sĩ thờ lạy Hài Nhi: Chúa Kitô tỏ mình cho muôn dân.";
SAINT1L.vi["The Exaltation of the Holy Cross"] = "Khải hoàn Thánh Giá, dấu chỉ ơn cứu độ chúng ta.";
SAINT1L.vi["The Holy Guardian Angels"] = "Mỗi người có một thiên thần giữ gìn và chuyển cầu cho mình.";
SAINT1L.vi["The Holy North American Martyrs"] = "Tám tu sĩ Dòng Tên tử đạo giữa các dân bản địa Bắc Mỹ.";
SAINT1L.vi["The Immaculate Conception"] = "Đức Mẹ được thụ thai không mắc tội tổ tông nhờ công nghiệp Chúa Kitô.";
SAINT1L.vi["The Immaculate Heart of Mary"] = "Trái Tim Vô Nhiễm Đức Mẹ, nơi nương náu hiền mẫu của tín hữu.";
SAINT1L.vi["The Nativity of Our Lord Jesus Christ"] = "Con Thiên Chúa giáng sinh tại Bêlem: Giáng Sinh.";
SAINT1L.vi["The Nativity of the Blessed Virgin"] = "Đức Mẹ chào đời, Đấng đầy ơn phúc, rạng đông ơn cứu độ.";
SAINT1L.vi["The Presentation of Jesus in the Temple"] = "Đức Mẹ và thánh Giuse dâng Hài Nhi trong đền thờ theo Luật.";
SAINT1L.vi["The Presentation of the Blessed Virgin Mary"] = "Em bé Maria được dâng cho Thiên Chúa trong đền thờ.";
SAINT1L.vi["The Seven Sorrows of the Blessed Virgin Mary"] = "Bảy sự đau đớn đã đâm thâu trái tim Người Mẹ bên thập giá.";
SAINT1L.vi["The Visitation of the Blessed Virgin Mary"] = "Đức Mẹ đi viếng bà Êlisabeth và hát kinh Ngợi Khen.";
SAINT1L.vi["Thomas"] = "Tông đồ đã nghi ngờ rồi đã tin: Lạy Chúa con và Thiên Chúa con!; đã rao giảng Tin Mừng tại Ấn Độ.";
SAINT1L.vi["Thomas Aquinas"] = "Tu sĩ Đa Minh đã kết hợp đức tin và lý trí trong Tổng Luận Thần Học; Tiến sĩ Thiên Thần.";
SAINT1L.vi["Thérèse of Lisieux"] = "Nữ tu Cát Minh Pháp của con đường nhỏ: yêu Chúa trong điều bé nhỏ.";
SAINT1L.vi["Timothy"] = "Môn đệ thánh Phaolô và giám mục đầu tiên của Êphêsô; chết tử đạo.";
SAINT1L.vi["Transfiguration of Our Lord"] = "Trên núi Tabor, Chúa Giêsu tỏ vinh quang cho Phêrô, Giacôbê và Gioan.";
SAINT1L.vi["Vincent de Paul"] = "Linh mục Pháp, cha của người nghèo; sáng lập Tu hội Truyền giáo và Nữ tử Bác Ái.";
SAINT1L.ar = {"Agatha":"شهيدة صقلية من القرن الثالث، مكرَّمة لطهارتها وثباتها أمام التعذيب.","Agnes":"شهيدة رومانية في الثانية عشرة فضَّلت الموت على إنكار المسيح.","All Saints":"عيد جميع القديسين، المعروفين والمجهولين، وشركة القديسين.","Aloysius Gonzaga":"يسوعي شاب مات وهو يعتني بالمطعونين في روما عن 23 عامًا.","Alphonsus Liguori":"أسقف إيطالي، مؤسس الفادين ومعلم الكنيسة.","Ambrose":"أسقف ميلانو، عمَّد القديس أوغسطين ودافع عن الإيمان بوعظه.","Andrew":"أخو بطرس وأول المدعوين؛ بشَّر اليونان ومات على صليب معقوف.","Annunciation of the Blessed Virgin Mary and the Incarnation of the Word of God":"بشارة الملاك جبرائيل لمريم: ابن الله صار إنسانًا.","Anthony of Padua":"فرنسيسكاني برتغالي، واعظ صانع عجائب؛ يُستعان به للأشياء المفقودة.","Anthony of the Desert":"مصري من القرن الثالث، أبو الرهبنة؛ عاش بالصلاة في البرية.","Athanasius":"أسقف الإسكندرية الذي دافع عن ألوهية المسيح ضد الآريوسية.","Augustine":"أسقف هيبو؛ بعد شباب مضطرب اهتدى وصار نور الكنيسة.","Barnabas":"رفيق بولس في رحلاته؛ حمل الإنجيل إلى قبرص وأنطاكية.","Bartholomew":"رسول (نثنائيل) بشَّر حتى الهند وأرمينيا حيث استشهد.","Basil the Great":"أسقف قيصرية، أبو الرهبنة الشرقية ومدافع ضد الآريوسية.","Benedict":"أبو الرهبنة الغربية؛ قانونه ما يزال يهدي الأديرة.","Bernard of Clairvaux":"رئيس دير سيسترسياني من القرن الثاني عشر، واعظ بليغ ومعلم الكنيسة.","Bonaventure":"فرنسيسكاني، الرئيس العام للرهبنة وكاردينال؛ المعلم السيرافي.","Boniface":"مرسل إنجليزي، رسول ألمانيا، استشهد وهو يثبِّت.","Catherine of Siena":"متصوفة ومعلمة نصحت الباباوات وأعادت البابوية إلى روما.","Cecilia":"شهيدة رومانية غنَّت لله في قلبها؛ شفيعة الموسيقيين.","Charles Borromeo":"رئيس أساقفة ميلانو الذي طبَّق مجمع ترنت بالمدارس والمعاهد.","Clare of Assisi":"أول تابعة لفرنسيس؛ أسست الكلاريس وأحبَّت الفقر.","Cyprian":"أسقف قرطاجة المهتدي من الوثنية؛ شهيد في الاضطهاد.","Cyril and Methodius":"أخوان من تسالونيكي، رسولا السلاف؛ وضعا أبجديتهم.","Dominic":"إسباني مؤسس الدومنيكان، وعَّاظ ضد الهرطقة.","Elizabeth of Hungary":"أميرة خدمت الفقراء والمرضى وبنت مستشفيات.","Frances Xavier Cabrini":"راهبة إيطالية أمريكية خدمت المهاجرين في الولايات المتحدة.","Francis Xavier":"يسوعي نافاري حمل الإنجيل إلى الهند واليابان.","Francis de Sales":"أسقف جنيف، معلم الوداعة والحياة التقية.","Francis of Assisi":"فقير أسيزي الذي تزوَّج الفقر وغنَّى للخليقة."};
SAINT1L.ko = {"Agatha":"3세기 시칠리아 순교자, 순결과 고난 중의 굳셈으로 공경받음.","Agnes":"그리스도를 부인하느니 죽음을 택한 열두 살 로마 순교자.","All Saints":"알려지고 알려지지 않은 모든 성인과 성인들의 통공 축일.","Aloysius Gonzaga":"23세에 로마에서 전염병 환자를 돌보다 숨진 젊은 예수회원.","Alphonsus Liguori":"이탈리아 주교, 레뎀프토리스트회 설립자, 교회 학자.","Ambrose":"밀라노 주교, 성 아우구스티노에게 세례를 주고 설교로 신앙을 지킴.","Andrew":"베드로의 형제이자 첫 부르심을 받은 이; 그리스에 복음을 전하고 X자 십자가에서 순교.","Annunciation of the Blessed Virgin Mary and the Incarnation of the Word of God":"가브리엘 천사가 마리아에게 고함: 천주의 아들이 사람이 되심.","Anthony of Padua":"포르투갈 프란치스코회원, 기적을 행한 설교가; 잃어버린 물건 때문에 도움을 청함.","Anthony of the Desert":"3세기 이집트인, 수도생활의 아버지; 사막에서 기도로 삶.","Athanasius":"알렉산드리아 주교, 아리우스주의에 맞서 그리스도의 천주성을 수호.","Augustine":"히포 주교; 방황하던 젊은 시절 뒤 회개하여 교회의 빛이 됨.","Barnabas":"바오로의 여행 동료; 키프로스와 안티오키아에 복음을 전함.","Bartholomew":"사도(나타나엘)로 인도와 아르메니아까지 전교하다 순교.","Basil the Great":"카이사리아 주교, 동방 수도생활의 아버지, 아리우스주의 반대 수호자.","Benedict":"서방 수도생활의 총대주교; 그의 규칙이 지금도 수도원을 이끎.","Bernard of Clairvaux":"12세기 시토회 대수도원장, 웅변의 설교가이자 교회 학자.","Bonaventure":"프란치스코회원, 수도회 총장, 추기경; 세라핌 학자.","Boniface":"영국 선교사, 독일의 사도, 견진성사를 주다가 순교.","Catherine of Siena":"교황들에게 조언하고 교황청을 로마로 되돌린 신비가이자 학자.","Cecilia":"마음으로 하느님을 노래한 로마 순교자; 음악가들의 수호자.","Charles Borromeo":"밀라노 대주교, 학교와 신학교로 트렌토 공의회를 적용.","Clare of Assisi":"프란치스코의 첫 추종자; 클라라회를 세우고 가난을 사랑.","Cyprian":"이교에서 회개한 카르타고 주교; 박해 중 순교.","Cyril and Methodius":"테살로니카 형제, 슬라브인의 사도; 그들의 알파벳을 만듦.","Dominic":"스페인인, 도미니코회 설립자, 이단에 맞선 설교자들.","Elizabeth of Hungary":"가난한 이와 병자를 섬기고 병원을 세운 공주.","Frances Xavier Cabrini":"미국에서 이민자를 섬긴 이탈리아계 미국인 수녀.","Francis Xavier":"나바라 출신 예수회원, 인도와 일본에 복음을 전함.","Francis de Sales":"제네바 주교, 온유와경건한 삶의 스승.","Francis of Assisi":"가난과 결혼하고 피조물을 노래한 아시시의 작은 가난뱅이."};
SAINT1L.ar["Gregory the Great"] = "بابا نظَّم الليتورجيا وبشَّر إنجلترا وكتب عن الكتاب المقدس.";
SAINT1L.ar["Holy Innocents"] = "أطفال بيت لحم الذين قتلهم هيرودس؛ أول الشهداء من أجل المسيح.";
SAINT1L.ar["Ignatius of Antioch"] = "أسقف شهيد في روما؛ رسائله تمجِّد الوحدة والقربان.";
SAINT1L.ar["Ignatius of Loyola"] = "جندي جريح مهتدٍ؛ أسس الرهبنة اليسوعية ورياضاته.";
SAINT1L.ar["Irenaeus"] = "أسقف ليون الذي حارب الهرطقات ودافع عن الإيمان الرسولي.";
SAINT1L.ar["James the Greater"] = "رسول، أول شهيد بين الاثني عشر؛ رفاته مكرَّمة في كومبوستيلا.";
SAINT1L.ar["Jerome"] = "ترجم الكتاب المقدس إلى اللاتينية (الفولغاتا)؛ معلم مكرَّس للكتاب.";
SAINT1L.ar["Joachim"] = "أبو العذراء مريم وزوج القديسة حنة؛ رجل تقي.";
SAINT1L.ar["John"] = "التلميذ الحبيب، إنجيلي؛ نُفي إلى بطمس وكتب الرؤيا.";
SAINT1L.ar["John Bosco"] = "كاهن توريني ربَّى الشباب الفقراء وأسس السالزيان.";
SAINT1L.ar["John Chrysostom"] = "بطريرك القسطنطينية، الفم الذهبي للوعظ.";
SAINT1L.ar["John Vianney"] = "كاهن آرس، راعٍ متواضع مكرَّس للاعتراف والمحبة.";
SAINT1L.ar["John of the Cross"] = "متصوف كرملي مع تريزا الأفيلية؛ غنَّى ليل النفس المظلم.";
SAINT1L.ar["John the Baptist"] = "سابق الرب؛ عمَّد يسوع في الأردن ومات من أجل الحق.";
SAINT1L.ar["Josaphat"] = "رئيس أساقفة شهيد عمل من أجل وحدة مسيحيي الشرق.";
SAINT1L.ar["Joseph"] = "حارس يسوع ومريم؛ رجل بار، شفيع الآباء والعمال.";
SAINT1L.ar["Justin of Naplouse"] = "فيلسوف مهتدٍ دافع عن الإيمان بكتاباته؛ شهيد في روما.";
SAINT1L.ar["Kateri Tekakwitha"] = "شابة موهوك، زنبقة الموهوك، أمينة للمسيح بين قومها.";
SAINT1L.ar["Lawrence"] = "شماس روماني وزَّع الأموال على الفقراء قبل استشهاده.";
SAINT1L.ar["Leo the Great"] = "بابا حدَّد الإيمان بالمسيح وخلَّص روما من أتيلا بكلمته.";
SAINT1L.ar["Lucy of Syracuse"] = "شهيدة شابة صقلية، رمز الطهارة والثبات.";
SAINT1L.ar["Luke"] = "طبيب ورفيق بولس؛ كتب الإنجيل الثالث وأعمال الرسل.";
SAINT1L.ar["Mark"] = "سكرتير بطرس في روما؛ دوَّن وعظه في إنجيله.";
SAINT1L.ar["Martha"] = "أخت مريم ولعازر، خادمة يسوع وامرأة عظيمة الإيمان.";
SAINT1L.ar["Martin of Tours"] = "جندي شاطر رداءه مع فقير؛ أسقف ورسول الغال.";
SAINT1L.ar["Mary Magdalen"] = "شاهدة الصليب وأول شهود القائم؛ مبشِّرة الرسل.";
SAINT1L.ar["Matthew"] = "عشَّار دعاه يسوع؛ إنجيله يقدِّم المسيح الموعود.";
SAINT1L.ar["Matthias"] = "اختاره الرسل ليملأ مكان يهوذا.";
SAINT1L.ar["Maximilian Kolbe"] = "فرنسيسكاني بذل حياته عن أب عائلة في أوشفيتز.";
SAINT1L.ar["Michael"] = "رئيس الملائكة أمير الجند السماوي؛ مَن مثل الله؟.";
SAINT1L.ar["Monica"] = "أم أوغسطين؛ بدموع وصلاة مثابرة رأته مهتديًا.";
SAINT1L.ar["Our Lady of Guadalupe"] = "سمراء التيبياك (1531)، أم وعلامة وحدة أمريكا.";
SAINT1L.ar["Our Lady of the Rosary"] = "لقب مريمي للوردية، ذكرى انتصار ليبانتو.";
SAINT1L.ar["Peter"] = "صياد الجليل، أول بابا؛ أنكر وبكى وثبَّت إخوته.";
SAINT1L.ar["Peter Claver"] = "يسوعي عمَّد وخدم مئات الآلاف من العبيد في قرطاجنة.";
SAINT1L.ar["Philip"] = "رسول أتى بنثنائيل إلى يسوع وطلب أن يرى الآب.";
SAINT1L.ar["Philip Neri"] = "كاهن روماني فرح، صديق الشباب؛ أسس الأوراتوريو.";
SAINT1L.ar["Pius X"] = "بابا قرَّب المناولة المتكررة إلى المؤمنين وحارب الحداثة.";
SAINT1L.ar["Scholastica"] = "أخت بندكتس ورئيسة دير؛ كرَّست حياتها للصلاة.";
SAINT1L.ar["Teresa of Avila"] = "مصلحة الكرمل ومعلمة؛ الله وحده يكفي.";
SAINT1L.ar["The Assumption of the Blessed Virgin Mary"] = "مريم في ختام حياتها أُصعدت إلى السماء بالنفس والجسد.";
SAINT1L.ar["The Baptism of Our Lord"] = "يسوع يعتمد على يد يوحنا: يبدأ حياته العلنية.";
SAINT1L.ar["The Conversion of Saint Paul"] = "شاول المضطهِد سقط في دمشق وصار رسول الأمم.";
SAINT1L.ar["The Epiphany of Our Lord"] = "المجوس يسجدون للطفل: المسيح يظهر لجميع الأمم.";
SAINT1L.ar["The Exaltation of the Holy Cross"] = "ظفر الصليب المقدس، علامة خلاصنا.";
SAINT1L.ar["The Holy Guardian Angels"] = "لكل إنسان ملاك يحرسه ويشفع فيه.";
SAINT1L.ar["The Holy North American Martyrs"] = "ثمانية يسوعيين شهداء بين الشعوب الأصلية في أمريكا الشمالية.";
SAINT1L.ar["The Immaculate Conception"] = "حُبل بمريم بلا دنس أصلي باستحقاقات المسيح.";
SAINT1L.ar["The Immaculate Heart of Mary"] = "قلب مريم الطاهر، ملجأ المؤمنين الأمومي.";
SAINT1L.ar["The Nativity of Our Lord Jesus Christ"] = "ابن الله يولد في بيت لحم: الميلاد.";
SAINT1L.ar["The Nativity of the Blessed Virgin"] = "تولد مريم، الممتلئة نعمة، فجر الخلاص.";
SAINT1L.ar["The Presentation of Jesus in the Temple"] = "مريم ويوسف يقدِّمان الطفل في الهيكل بحسب الشريعة.";
SAINT1L.ar["The Presentation of the Blessed Virgin Mary"] = "الطفلة مريم تُقدَّم لله في الهيكل.";
SAINT1L.ar["The Seven Sorrows of the Blessed Virgin Mary"] = "الأوجاع السبعة التي اخترقت قلب الأم قرب الصليب.";
SAINT1L.ar["The Visitation of the Blessed Virgin Mary"] = "مريم تزور أليصابات وتنشد التعظيمة.";
SAINT1L.ar["Thomas"] = "رسول شكَّ وآمن: ربي وإلهي!؛ بشَّر الهند.";
SAINT1L.ar["Thomas Aquinas"] = "دومنيكاني جمع الإيمان والعقل في الخلاصة اللاهوتية؛ المعلم الملائكي.";
SAINT1L.ar["Thérèse of Lisieux"] = "كرملية فرنسية للطريق الصغير: أن تحب الله في الصغير.";
SAINT1L.ar["Timothy"] = "تلميذ بولس وأول أسقف لأفسس؛ مات شهيدًا.";
SAINT1L.ar["Transfiguration of Our Lord"] = "على الطابور يُظهر يسوع مجده لبطرس ويعقوب ويوحنا.";
SAINT1L.ar["Vincent de Paul"] = "كاهن فرنسي أبو الفقراء؛ أسس اللعازريين وبنات المحبة.";
SAINT1L.ko["Gregory the Great"] = "전례를 정비하고 영국에 복음을 전하며 성서에 관해 저술한 교황.";
SAINT1L.ko["Holy Innocents"] = "헤로데에게 살해당한 베들레헴 아기들; 그리스도를 위한 첫 순교자들.";
SAINT1L.ko["Ignatius of Antioch"] = "로마에서 순교한 주교; 서간에서 일치와 성체를 찬양.";
SAINT1L.ko["Ignatius of Loyola"] = "부상당하고 회개한 군인; 예수회와 피정을 설립.";
SAINT1L.ko["Irenaeus"] = "이단을 물리치고 사도적 신앙을 수호한 리옹 주교.";
SAINT1L.ko["James the Greater"] = "사도, 열둘 중 첫 순교자; 유해가 콤포스텔라에서 공경받음.";
SAINT1L.ko["Jerome"] = "성서를 라틴어로 번역(불가타); 성서에 헌신한 학자.";
SAINT1L.ko["Joachim"] = "동정 마리아의 아버지이자 성 안나의 남편;경건한 사람.";
SAINT1L.ko["John"] = "사랑받던 제자, 복음사가; 파트모스로 유배되어 묵시록을 기록.";
SAINT1L.ko["John Bosco"] = "가난한 청소년을 교육하고 살레시오회를 세운 토리노 사제.";
SAINT1L.ko["John Chrysostom"] = "콘스탄티노플 총대주교, 설교의 황금 입.";
SAINT1L.ko["John Vianney"] = "아르스의 본당 신부, 고해와 자선에 헌신한 겸손한 목자.";
SAINT1L.ko["John of the Cross"] = "아빌라의 데레사와 동행한 가르멜 신비가; 영혼의 어두운 밤을 노래.";
SAINT1L.ko["John the Baptist"] = "주님의 선구자; 요르단강에서 예수님께 세례를 주고 진리를 위해 죽음.";
SAINT1L.ko["Josaphat"] = "동방 그리스도인들의 일치를 위해 일한 순교 대주교.";
SAINT1L.ko["Joseph"] = "예수님과 마리아의 수호자; 의로운 사람, 아버지와 일하는 이들의 수호자.";
SAINT1L.ko["Justin of Naplouse"] = "회개한 철학자로 저술로 신앙을 수호; 로마에서 순교.";
SAINT1L.ko["Kateri Tekakwitha"] = "모호크 소녀, 모호크의 백합, 동족 가운데 그리스도께 충실.";
SAINT1L.ko["Lawrence"] = "순교 전 재산을 가난한 이들에게 나눠준 로마 부제.";
SAINT1L.ko["Leo the Great"] = "그리스도 신앙을 정의하고 말로 로마를 아틸라에게서 구한 교황.";
SAINT1L.ko["Lucy of Syracuse"] = "시라쿠사 소녀 순교자, 순결과 굳셈의 상징.";
SAINT1L.ko["Luke"] = "의사이자 바오로의 동료; 제3복음과 사도행전을 기록.";
SAINT1L.ko["Mark"] = "로마에서 베드로의 비서; 그의 설교를 복음서에 기록.";
SAINT1L.ko["Martha"] = "마리아와 라자로의 자매, 예수님을 섬긴 큰 믿음의 여인.";
SAINT1L.ko["Martin of Tours"] = "가난한 이와 외투를 나눈 군인; 주교이자 갈리아의 사도.";
SAINT1L.ko["Mary Magdalen"] = "십자가의 증인이자 부활하신 분의 첫 증인; 사도들에게 알린 이.";
SAINT1L.ko["Matthew"] = "예수님께 부르심을 받은 세리; 그의 복음은 약속된 그리스도를 제시.";
SAINT1L.ko["Matthias"] = "유다스의 자리를 채우도록 사도들이 뽑은 이.";
SAINT1L.ko["Maximilian Kolbe"] = "아우슈비츠에서 한 가장을 위해 목숨을 바친 프란치스코회원.";
SAINT1L.ko["Michael"] = "천상 군대의 왕자 대천사; 누가 하느님 같으랴?.";
SAINT1L.ko["Monica"] = "아우구스티노의 어머니; 눈물과 항구한 기도로 아들의 회개를 봄.";
SAINT1L.ko["Our Lady of Guadalupe"] = "테페약의 검은 성모(1531), 아메리카의 어머니이자 일치의 표지.";
SAINT1L.ko["Our Lady of the Rosary"] = "묵주 성모 호칭, 레판토 승리의 기념.";
SAINT1L.ko["Peter"] = "갈릴래아 어부, 첫 교황; 부인하고 울고 형제들을 굳게 함.";
SAINT1L.ko["Peter Claver"] = "카르타헤나에서 수십만 노예에게 세례를 주고 섬긴 예수회원.";
SAINT1L.ko["Philip"] = "나타나엘을 예수님께 이끈 사도이자 성부를 뵙기 청한 이.";
SAINT1L.ko["Philip Neri"] = "로마의 유쾌한 사제, 청소년의 벗; 오라토리오회 설립.";
SAINT1L.ko["Pius X"] = "잦은 영성체를 신자들에게 가깝게 하고 현대주의에 맞선 교황.";
SAINT1L.ko["Scholastica"] = "베네딕토의 자매이자 대수녀원장; 생애를 기도에 봉헌.";
SAINT1L.ko["Teresa of Avila"] = "가르멜 개혁자이자 학자; 오직 하느님으로 충분하다.";
SAINT1L.ko["The Assumption of the Blessed Virgin Mary"] = "마리아가 생애 끝에 영혼과 육신으로 하늘에 올림받음.";
SAINT1L.ko["The Baptism of Our Lord"] = "예수님이 요한에게 세례받으심: 공생활 시작.";
SAINT1L.ko["The Conversion of Saint Paul"] = "박해자 사울이 다마스쿠스에서 쓰러져 만민의 사도가 됨.";
SAINT1L.ko["The Epiphany of Our Lord"] = "박사들이 아기를 경배: 그리스도가 만민에게 나타나심.";
SAINT1L.ko["The Exaltation of the Holy Cross"] = "거룩한 십자가의 승리, 우리 구원의 표지.";
SAINT1L.ko["The Holy Guardian Angels"] = "모든 사람에게는 수호하고 전구하는 천사가 있음.";
SAINT1L.ko["The Holy North American Martyrs"] = "북아메리카 원주민 가운데 순교한 여덟 예수회원.";
SAINT1L.ko["The Immaculate Conception"] = "마리아가 그리스도의 공로로 원죄 없이 잉태되심.";
SAINT1L.ko["The Immaculate Heart of Mary"] = "마리아의 티 없으신 성심, 신자들의 자모로운 피난처.";
