SACRAMENT_I18N.tl = [{"h":"Rehistro sa parokya","p":"Upang maging rehistradong parokyano dumaan sa opisina (Lun–Huw 9 AM–4 PM, Biy 9 AM–1 PM) o tumawag sa (505) 753-3345. Kailangan para sa mga ninong, binyag at ilang papeles."},{"h":"Binyag","p":"Maging rehistradong parokyano. Dumaan sa opisina para sa listahan ng requirements at dokumento (mga batang wala pang 7 taon at mga ninong). Pre-baptismal na klase: Lunes 6:30 PM sa opisina (magulang at ninong)."},{"h":"Kasal","p":"Tumawag sa rektoriya nang hindi bababa sa anim na buwan bago. Kailangan ang pre-marital na klase bago magtakda ng petsa."},{"h":"Unang Pakikinabang","p":"Paghahanda sa Pananampalataya. Espanyol: Diak. Ernest Salazar (505) 412-7632 · Ingles: Alice Lucero (505) 747-9176."},{"h":"Kumpil","p":"Paghahanda sa Pananampalataya at OCIA. Magtanong sa opisina o sa formation team."},{"h":"Puneral","p":"Tumawag sa rektoriya (505) 753-3345 upang ayusin kasama ng kura ang Misa ng puneral at pagdamay sa pamilya."},{"h":"Sementeryo (lote)","p":"Para sa lote sa sementeryo ng parokya, kontakin ang opisina: (505) 753-3345 · holycross.admoffice@gmail.com."},{"h":"OCIA at RICA (Espanyol)","p":"Diak. Ernest Salazar (DRE): (505) 412-7632 · deaconernest.salazar16@gmail.com"},{"h":"Paghubog sa Pananampalataya (Ingles) at OCIA Ingles","p":"Alice Lucero: (505) 747-9176 · Melissa Esquibel (OCIA Ingles): (505) 753-3345"},{"h":"Pastoral ng maysakit (homebound)","p":"Angelica Juarez: (505) 692-7249 · angelicajuarez2114@gmail.com"},{"h":"Pagkakasundo","p":"Sabado 4:00–5:15 PM o ayon sa kasunduan."},{"h":"Opisina ng parokya","p":"Lun–Huw 9 AM–4 PM (sarado 1–2 PM) · Biy 9 AM–1 PM · (505) 753-3345 · holycross.admoffice@gmail.com · P.O. Box 1228, Santa Cruz, NM 87567"}];
SACRAMENT_I18N.vi = [{"h":"Ghi danh giáo xứ","p":"Để thành giáo dân ghi danh, ghé văn phòng (Thứ 2–5 lúc 9 giờ sáng–4 giờ chiều, Thứ 6 lúc 9 giờ sáng–1 giờ chiều) hoặc gọi (505) 753-3345. Bắt buộc cho người đỡ đầu, rửa tội và một số thủ tục."},{"h":"Rửa Tội","p":"Phải là giáo dân ghi danh. Ghé văn phòng lấy tờ yêu cầu và giấy tờ (trẻ dưới 7 tuổi và người đỡ đầu). Lớp tiền rửa tội: thứ hai 6:30 chiều tại văn phòng (cha mẹ và người đỡ đầu)."},{"h":"Hôn Phối","p":"Gọi nhà xứ ít nhất sáu tháng trước. Bắt buộc học lớp tiền hôn nhân mới được đặt ngày."},{"h":"Rước Lễ Lần Đầu","p":"Chuẩn bị qua Giáo lý Đức tin. Tiếng Tây Ban Nha: Phó tế Ernest Salazar (505) 412-7632 · Tiếng Anh: Alice Lucero (505) 747-9176."},{"h":"Thêm Sức","p":"Chuẩn bị qua Giáo lý Đức tin và OCIA. Hỏi tại văn phòng hoặc nhóm giáo lý."},{"h":"An táng","p":"Gọi nhà xứ (505) 753-3345 để cùng cha xứ lo lễ an táng và đồng hành với gia đình."},{"h":"Nghĩa trang (lô đất)","p":"Muốn biết về lô đất trong nghĩa trang giáo xứ, liên hệ văn phòng: (505) 753-3345 · holycross.admoffice@gmail.com."},{"h":"OCIA và RICA (tiếng Tây Ban Nha)","p":"Phó tế Ernest Salazar (DRE): (505) 412-7632 · deaconernest.salazar16@gmail.com"},{"h":"Giáo lý Đức tin (tiếng Anh) và OCIA tiếng Anh","p":"Alice Lucero: (505) 747-9176 · Melissa Esquibel (OCIA tiếng Anh): (505) 753-3345"},{"h":"Mục vụ bệnh nhân (homebound)","p":"Angelica Juarez: (505) 692-7249 · angelicajuarez2114@gmail.com"},{"h":"Hòa Giải","p":"Thứ bảy 4:00–5:15 chiều hoặc hẹn riêng."},{"h":"Văn phòng giáo xứ","p":"Thứ 2–5 lúc 9 giờ sáng–4 giờ chiều (nghỉ 1–2 giờ chiều) · Thứ 6 lúc 9 giờ sáng–1 giờ chiều · (505) 753-3345 · holycross.admoffice@gmail.com · P.O. Box 1228, Santa Cruz, NM 87567"}];
SACRAMENT_I18N.ar = [{"h":"التسجيل في الرعية","p":"لتصبح من أبناء الرعية المسجلين مرّ على المكتب (الاثنين–الخميس 9 صباحًا–4 مساءً، الجمعة 9 صباحًا–1 مساءً) أو اتصل (505) 753-3345. مطلوب للعرّابين والمعمودية وبعض المعاملات."},{"h":"المعمودية","p":"كن من أبناء الرعية المسجلين. مرّ على المكتب لأخذ ورقة الشروط والمستندات (الأطفال دون 7 سنوات والعرّابون). درس ما قبل المعمودية: الاثنين 6:30 مساءً في المكتب (الأهل والعرّابون)."},{"h":"الزواج","p":"اتصل بدار الكاهن قبل ستة أشهر على الأقل. دروس ما قبل الزواج مطلوبة لتثبيت الموعد."},{"h":"المناولة الأولى","p":"الإعداد عبر التنشئة الإيمانية. بالإسبانية: الشماس إرنست سالازار (505) 412-7632 · بالإنجليزية: أليس لوسيرو (505) 747-9176."},{"h":"التثبيت","p":"الإعداد عبر التنشئة الإيمانية وOCIA. اسأل في المكتب أو فريق التنشئة."},{"h":"الجنازات","p":"اتصل بدار الكاهن (505) 753-3345 لتنسيق قداس الجناز ومرافقة العائلة مع كاهن الرعية."},{"h":"المقبرة (قطعة)","p":"لمعلومات عن قطع مقبرة الرعية، اتصل بالمكتب: (505) 753-3345 · holycross.admoffice@gmail.com."},{"h":"OCIA وRICA (بالإسبانية)","p":"الشماس إرنست سالازار (DRE): (505) 412-7632 · deaconernest.salazar16@gmail.com"},{"h":"التنشئة الإيمانية (بالإنجليزية) وOCIA الإنجليزية","p":"أليس لوسيرو: (505) 747-9176 · ميليسا إسكيبيل (OCIA الإنجليزية): (505) 753-3345"},{"h":"رعوية المرضى (homebound)","p":"أنجيليكا خواريز: (505) 692-7249 · angelicajuarez2114@gmail.com"},{"h":"المصالحة","p":"السبت 4:00–5:15 مساءً أو بموعد."},{"h":"مكتب الرعية","p":"الاثنين–الخميس 9 صباحًا–4 مساءً (مغلق 1–2 مساءً) · الجمعة 9 صباحًا–1 مساءً · (505) 753-3345 · holycross.admoffice@gmail.com · P.O. Box 1228, Santa Cruz, NM 87567"}];
SACRAMENT_I18N.ko = [{"h":"교적 등록","p":"등록 교우가 되려면 사무실에 오세요 (월–목 오전 9시–오후 4시, 금 오전 9시–오후 1시) 또는 (505) 753-3345로 전화하세요. 대부모, 세례, 일부 절차에 필요합니다."},{"h":"세례","p":"등록 교우여야 합니다. 사무실에서 요건 안내문과 서류를 받으세요 (7세 미만 어린이와 대부모). 세례 전 교육: 월요일 오후 6:30 사무실 (부모와 대부모)."},{"h":"혼인","p":"최소 6개월 전에 사제관에 연락하세요. 날짜 확정 전에 혼인 교육을 이수해야 합니다."},{"h":"첫영성체","p":"신앙 교육을 통한 준비. 스페인어: Ernest Salazar 부제 (505) 412-7632 · 영어: Alice Lucero (505) 747-9176."},{"h":"견진","p":"신앙 교육과 OCIA를 통한 준비. 사무실이나 교육팀에 문의하세요."},{"h":"장례","p":"본당 신부님과 장례미사 및 유가족 동행을 상의하려면 사제관 (505) 753-3345로 연락하세요."},{"h":"묘지 (묘역)","p":"본당 묘지 안내: 사무실 (505) 753-3345 · holycross.admoffice@gmail.com."},{"h":"OCIA 및 RICA (스페인어)","p":"Ernest Salazar 부제 (DRE): (505) 412-7632 · deaconernest.salazar16@gmail.com"},{"h":"신앙 교육 (영어) 및 영어 OCIA","p":"Alice Lucero: (505) 747-9176 · Melissa Esquibel (영어 OCIA): (505) 753-3345"},{"h":"병자 사목 (homebound)","p":"Angelica Juarez: (505) 692-7249 · angelicajuarez2114@gmail.com"},{"h":"고해","p":"토요일 오후 4:00–5:15 또는 예약."},{"h":"본당 사무실","p":"월–목 오전 9시–오후 4시 (오후 1–2시 휴무) · 금 오전 9시–오후 1시 · (505) 753-3345 · holycross.admoffice@gmail.com · P.O. Box 1228, Santa Cruz, NM 87567"}];
